    28→public class AppConfig {
    29→
    30→    private final KeycloakJwtAuthenticationConverter keycloakJwtAuthenticationConverter;
    31→
    32→    /**
    33→     * Chaîne de sécurité dédiée aux anciennes API (/previous/**).
