     7→/**
     8→ * Utilitaires pour la gestion de la sécurité et l'extraction des informations du token JWT
     9→ */
    10→@Component
    11→public class SecurityUtils {
    12→
    13→    /**
    14→     * Extrait le client_id du token JWT courant
    15→     *
    16→     * @return le client_id du token JWT
    17→     * @throws IllegalStateException si aucun token n'est présent ou si le client_id est manquant
    18→     */
    19→    public static String getCurrentClientId() {
    20→        var authentication = SecurityContextHolder.getContext().getAuthentication();
    21→
    22→        if (authentication == null || !(authentication.getPrincipal() instanceof Jwt jwt)) {
    23→            throw new IllegalStateException("Aucun token JWT valide trouvé dans le contexte de sécurité");
    24→        }
    25→
    26→        String clientId = jwt.getClaimAsString("client_id");
    27→        if (clientId == null || clientId.trim().isEmpty()) {
    28→            throw new IllegalStateException("Le client_id est manquant dans le token JWT");
    29→        }
    30→
    31→        return clientId;
    32→    }
    33→
    34→    /**
    35→     * Extrait une claim spécifique du token JWT courant
    36→     *
    37→     * @param claimName nom de la claim à extraire
    38→     * @return la valeur de la claim
    39→     * @throws IllegalStateException si aucun token n'est présent
    40→     */
    41→    public static String getClaim(String claimName) {
    42→        var authentication = SecurityContextHolder.getContext().getAuthentication();
    43→
    44→        if (authentication == null || !(authentication.getPrincipal() instanceof Jwt jwt)) {
    45→            throw new IllegalStateException("Aucun token JWT valide trouvé dans le contexte de sécurité");
    46→        }
    47→
    48→        return jwt.getClaimAsString(claimName);
    49→    }
    50→
    51→    /**
    52→     * Vérifie si l'utilisateur courant est authentifié avec un token JWT
    53→     *
    54→     * @return true si authentifié avec JWT, false sinon
    55→     */
    56→    public static boolean isAuthenticated() {
    57→        var authentication = SecurityContextHolder.getContext().getAuthentication();
    58→        return authentication != null &&
    59→                authentication.isAuthenticated() &&
