   671→    private MtnGatewayConfig getMtnConfigForCountry(DepositGateways gateway, String countryCode, boolean isDeposit) throws Exception {
   672→        try {
   673→            // Récupérer le JSON brut des variables (objet JSON indexé par pays)
   674→            String variablesJson = depositGatewaysRepository.findVariablesJsonById(gateway.getId());
   675→            if (variablesJson == null || variablesJson.isBlank()) {
