   681→                    new TypeReference<Map<String, Object>>() {
   682→                    }
   683→            );
   684→
   685→            Object cfg = variables.get(countryCode);
   686→            if (!(cfg instanceof Map)) {
   687→                throw new IllegalArgumentException("Configuration MTN non trouvée pour le pays: " + countryCode);
   688→            }
   689→            Map<String, Object> countryConfig = (Map<String, Object>) cfg;
   690→
   691→            Object coll = isDeposit ? countryConfig.get("collection") : countryConfig.get("disbursement");
   692→            if (!(coll instanceof Map)) {
   693→                throw new IllegalArgumentException("Configuration collection MTN manquante pour le pays: " + countryCode);
   694→            }
   695→            Map<String, Object> collectionConfig = (Map<String, Object>) coll;
   696→
