   700→            String environment = (String) countryConfig.get("env");
   701→
   702→            if (apiKey == null || secretKey == null || subscriptionKey == null || environment == null) {
   703→                throw new IllegalArgumentException("Paramètres MTN incomplets pour le pays: " + countryCode);
