    27→@RequiredArgsConstructor
    28→public class AppConfig {
    29→
    30→    private final KeycloakJwtAuthenticationConverter keycloakJwtAuthenticationConverter;
    31→
    32→    /**
    33→     * Chaîne de sécurité dédiée aux anciennes API (/previous/**).
    34→     * Aucune authentification Spring Security ici : tout est permitAll,
    35→     * l'auth est gérée par nos filtres LegacyApi*Filter.
    36→     */
    37→    @Bean
    38→    public SecurityFilterChain previousApiSecurity(HttpSecurity http) throws Exception {
    39→        http
    40→                .securityMatcher(PREVIOUS_API_PREFIX + "/**")
    41→                .authorizeHttpRequests(authz -> authz
    42→                        .anyRequest().permitAll()
    43→                )
    44→                .csrf(AbstractHttpConfigurer::disable);
    45→        // Surtout pas de oauth2ResourceServer ici
    46→        return http.build();
    47→    }
    48→
    49→    /**
    50→     * Chaîne de sécurité principale pour le reste des endpoints (hors /previous/**).
    51→     */
    52→    @Bean
    53→    public SecurityFilterChain mainSecurity(HttpSecurity http) throws Exception {
    54→        http
    55→                .authorizeHttpRequests(authz -> authz
    56→                        .requestMatchers(
    57→                                "/actuator/health",
    58→                                "/actuator/**",
    59→                                "/public/**",
    60→                                "/p/**",  // Pages de paiement et reçus publics
    61→                                "/test/public/**",
    62→                                "/swagger-ui.html",
    63→                                "/swagger-ui/**",
    64→                                "/v3/api-docs/**",
    65→                                // Static assets
    66→                                "/styles/**",
    67→                                "/js/**",
    68→                                "/images/**",
    69→                                "/favicon.ico"
    70→                        ).permitAll()
    71→                        .requestMatchers("/test/api/v2/**").authenticated()
    72→                        .anyRequest().authenticated()
    73→                )
    74→                .exceptionHandling(ex -> ex
    75→                        .authenticationEntryPoint(unauthorizedEntryPoint())
    76→                )
    77→                .oauth2ResourceServer(oauth2 -> oauth2
    78→                        .jwt(jwt -> jwt.jwtAuthenticationConverter(keycloakJwtAuthenticationConverter))
    79→                )
    80→                .csrf(AbstractHttpConfigurer::disable);
    81→        return http.build();
    82→    }
    83→
    84→    @Bean
    85→    public AuthenticationEntryPoint unauthorizedEntryPoint() {
    86→        return (request, response, authException) -> {
    87→            response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
    88→            response.setContentType("application/json");
    89→            response.getWriter().write("{\"error\":\"Unauthorized\"}");
    90→        };
    91→    }
