     3→import lombok.extern.slf4j.Slf4j;
     4→import org.springframework.core.convert.converter.Converter;
     5→import org.springframework.security.authentication.AbstractAuthenticationToken;
     6→import org.springframework.security.core.GrantedAuthority;
     7→import org.springframework.security.core.authority.SimpleGrantedAuthority;
     8→import org.springframework.security.oauth2.jwt.Jwt;
     9→import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;
    10→import org.springframework.stereotype.Component;
    11→
    12→import java.util.*;
    13→import java.util.stream.Collectors;
    14→
    15→/**
    16→ * Convertisseur JWT personnalisé pour Keycloak.
    17→ *
    18→ * Transforme les realm roles composites (api:deposit, api:withdraw, etc.) en scopes
    19→ * utilisables avec @PreAuthorize("hasAuthority('SCOPE_api:deposit')").
    20→ *
    21→ * Structure JWT Keycloak attendue:
    22→ * {
    23→ *   "realm_access": {
    24→ *     "roles": ["MARCHAND", "api:deposit", "api:withdraw", ...]
    25→ *   }
    26→ * }
    27→ *
    28→ * Résultat:
    29→ * - ROLE_MARCHAND (pour hasRole('MARCHAND'))
    30→ * - SCOPE_api:deposit (pour hasAuthority('SCOPE_api:deposit'))
    31→ * - SCOPE_api:withdraw (pour hasAuthority('SCOPE_api:withdraw'))
    32→ */
    33→@Slf4j
    34→@Component
    35→public class KeycloakJwtAuthenticationConverter implements Converter<Jwt, AbstractAuthenticationToken> {
    36→
    37→    private static final String REALM_ACCESS_CLAIM = "realm_access";
    38→    private static final String ROLES_CLAIM = "roles";
    39→    private static final String ROLE_PREFIX = "ROLE_";
    40→    private static final String SCOPE_PREFIX = "SCOPE_";
    41→    private static final String API_SCOPE_PREFIX = "api:";
    42→
    43→    @Override
    44→    public AbstractAuthenticationToken convert(Jwt jwt) {
    45→        Collection<GrantedAuthority> authorities = extractAuthorities(jwt);
    46→
    47→        String principalName = extractPrincipalName(jwt);
    48→
    49→        log.debug("[JWT-CONVERTER] Token converti pour: {}, authorities: {}",
    50→                principalName, authorities);
    51→
    52→        return new JwtAuthenticationToken(jwt, authorities, principalName);
    53→    }
    54→
    55→    /**
    56→     * Extrait les authorities depuis le JWT Keycloak.
    57→     *
    58→     * - Les rôles "api:*" deviennent des SCOPE_api:* (pour @PreAuthorize avec hasAuthority)
    59→     */
    60→    private Collection<GrantedAuthority> extractAuthorities(Jwt jwt) {
    61→        Set<GrantedAuthority> authorities = new HashSet<>();
    62→
    63→        // 1. Extraire les realm roles
    64→        Map<String, Object> realmAccess = jwt.getClaimAsMap(REALM_ACCESS_CLAIM);
    65→        if (realmAccess != null && realmAccess.containsKey(ROLES_CLAIM)) {
    66→            @SuppressWarnings("unchecked")
    67→            List<String> roles = (List<String>) realmAccess.get(ROLES_CLAIM);
    68→
    69→            for (String role : roles) {
    70→                if (role.startsWith(API_SCOPE_PREFIX)) {
    71→                    // Rôles api:* → convertis en SCOPE_api:* pour vérification de scope
    72→                    authorities.add(new SimpleGrantedAuthority(SCOPE_PREFIX + role));
    73→                    log.trace("[JWT-CONVERTER] Scope ajouté: {}", SCOPE_PREFIX + role);
    74→                } else {
    75→                    // Rôles normaux (MARCHAND, API_SUPER) → ROLE_*
    76→                    authorities.add(new SimpleGrantedAuthority(ROLE_PREFIX + role));
    77→                    log.trace("[JWT-CONVERTER] Role ajouté: {}", ROLE_PREFIX + role);
    78→                }
    79→            }
    80→        }
    81→
    82→        // 2. Ajouter les scopes du token JWT (claim "scope") si présents
    83→        String scopeClaim = jwt.getClaimAsString("scope");
    84→        if (scopeClaim != null && !scopeClaim.isBlank()) {
    85→            Arrays.stream(scopeClaim.split("\\s+"))
    86→                    .filter(s -> !s.isBlank())
    87→                    .map(s -> new SimpleGrantedAuthority(SCOPE_PREFIX + s))
    88→                    .forEach(authorities::add);
    89→        }
    90→
    91→        return authorities;
    92→    }
    93→
    94→    /**
    95→     * Extrait le nom principal depuis le JWT.
    96→     * Priorité: preferred_username > client_id > sub
    97→     */
    98→    private String extractPrincipalName(Jwt jwt) {
    99→        String preferredUsername = jwt.getClaimAsString("preferred_username");
   100→        if (preferredUsername != null && !preferredUsername.isBlank()) {
   101→            return preferredUsername;
   102→        }
   103→
   104→        String clientId = jwt.getClaimAsString("client_id");
   105→        if (clientId != null && !clientId.isBlank()) {
   106→            return clientId;
   107→        }
   108→
   109→        return jwt.getSubject();
   110→    }
   111→}
