export function useDepositByIdPolling(id, shouldPoll) {
  const { data, error } = useSWR(
    id ? `/deposits/${id}` : null,
    {
      refreshInterval: shouldPoll ? 5000 : 0,
      keepPreviousData: true,
      revalidateOnFocus: false,
      dedupingInterval: 3000,
    },
  );
  return {
    data,
    loading: !data && !error,
    error,
  };
}

