    try {
      parsedVariables = JSON.parse(gatewayFind.variables);
    } catch (parseErr) {
      await Log.create({ message: `MTN Payment Error: Failed to parse gateway variables - ${parseErr.message}` });
      throw new Error('Invalid MTN gateway configuration');
    }

    const variables = parsedVariables[countryCode];

    if (!variables) {
      const availableCountries = Object.keys(parsedVariables).join(', ');
      await Log.create({
        message: `MTN Payment Error: No config for ${countryCode}. Available: ${availableCountries}`,
      });
      throw new Error(`MTN is not configured for country: ${countryCode}. Available countries: ${availableCountries}`);
    }

