          uri: `${baseURL}/disbursement/v1_0/transfer/${reference}`,
          json: true,
          headers: {
            Accept: 'application/json',
            Authorization: `Bearer ${accessData.access_token}`,
            'Ocp-Apim-Subscription-Key': gateway.ex1,
            'X-Target-Environment': variables.env,
            'X-Reference-Id': reference,
          },
        });
        await Log.create({
          message: `check if well register in mtn (ref: ${reference}) amount : ${data.amount}
        currency: ${data.currency}
        externalId: ${data.id} message erreur ${response.reason} message ${response.message}`,
        });

        console.log({ response });
        if (response.status === 'SUCCESSFUL') {
          // Note: Withdraw success updates are usually less critical for double-spend (since user gets money OUT),
          // but good to lock to avoid double confirmation logging/notifying.
          transaction = await db.sequelize.transaction();
          const withdrawData = await Withdraw.findByPk(data.id, { lock: transaction.LOCK.UPDATE, transaction });

          if (withdrawData.status !== 'pending') {
            await transaction.commit();
            clearInterval(checkInterval);
            validated = true;
            return;
          }

          await Withdraw.update({ status: 'success' }, { where: { id: withdrawData.id }, transaction });

          // Non-bloquant: notification gateway
          rp({
            method: 'POST',
            uri: `${API_V3_URL}/webhook/payout`,
            json: true,
            body: {
              status: 'success',
              withdrawId: withdrawData.id,
            },
          }).catch((err) => Log.create({ message: `Gateway payout notification failed: ${err.message}` }));

          await Request.update({ status: 'success' },
            { where: { depotAndWithdrawID: withdrawData.id, type: 'withdraw' }, transaction });

          await Log.create({ message: `MTN confirmed payment for withdraw #${withdrawData.id} (ref: ${reference})` }, { transaction });

          await transaction.commit();

          validated = true;
          clearInterval(checkInterval);
          await Log.create({ message: `is validated from mtn (ref: ${reference})` });
        }
      } catch (err) {
        if (transaction) await transaction.rollback();
      }
    }, 30000);

    setTimeout(async () => {
      if (validated) return;
      let transaction;
      try {
        transaction = await db.sequelize.transaction();
        const withdrawData = await Withdraw.findByPk(data.id, { lock: transaction.LOCK.UPDATE, transaction });

        clearInterval(checkInterval);
        if (withdrawData.status === 'pending') {
          const balanceResult = await addBalance(withdrawData.amount, withdrawData.currency, withdrawData.userId, 12, { transaction }, `Remboursement withdraw #${withdrawData.id} - timeout MTN`);
          if (balanceResult.error) {
            await Log.create({ message: `MTN withdraw #${withdrawData.id} - refund addBalance failed: ${balanceResult.error}` }, { transaction });
            await notifyAddBalanceError('Withdraw MTN Refund', withdrawData.id, withdrawData.amount, withdrawData.currency, withdrawData.userId, balanceResult.error);
            throw new Error(`Failed to refund balance: ${balanceResult.error}`);
          }
          await Withdraw.update({ payment_status: false, status: 'failed' }, {
            where: { id: withdrawData.id },
            transaction,
          });

          // Non-bloquant: notification gateway
          rp({
            method: 'POST',
            uri: `${API_V3_URL}/webhook/payout`,
            json: true,
            body: {
              status: 'failed',
              withdrawId: withdrawData.id,
            },
          }).catch((err) => Log.create({ message: `Gateway payout notification failed: ${err.message}` }));

          await Request.update({ status: 'failed' },
            { where: { depotAndWithdrawID: withdrawData.id, type: 'withdraw' }, transaction });

          await Log.create({ message: `MTN declined payment for withdraw #${withdrawData.id} (ref: ${reference})` }, { transaction });
          await transaction.commit();
        } else {
          await transaction.commit();
        }
      } catch (err) {
        if (transaction) await transaction.rollback();
      }
    }, 360000);

    return 'pending';
  } catch (err) {
    return 'error';
  }
};

