```php
<?php
/**
 * Abstract Payment Gateway Base Class
 * Defines the contract for all payment implementations
 */
abstract class PaymentGateway {
    protected $pdo;
    protected $baseUrl;
    protected $environment;

    public function __construct(PDO $pdo) {
        $this->pdo = $pdo;
    }

    /**
     * Initialize a payment request
     * @param array $paymentData Contains: amount, phone, reference, description
     * @return array Response with status, transaction_id, redirect_url (if applicable)
     */
    abstract public function initiatePayment(array $paymentData): array;

    /**
     * Check payment status
     * @param string $transactionId
     * @return array Status information
     */
    abstract public function checkStatus(string $transactionId): array;

    /**
     * Handle callback/webhook from provider
     * @param array $callbackData
     * @return bool
     */
    abstract public function handleCallback(array $callbackData): bool;

    /**
     * Log transaction to database
     */
    protected function logTransaction(
        int $orderId,
        float $amount,
        string $mode,
        string $status,
        ?string $transactionId = null,
        ?string $providerRef = null,
        ?string $phone = null,
        ?string $details = null
    ): int {
        $stmt = $this->pdo->prepare(
            "INSERT INTO paiements (commande_id, montant, mode_paiement, statut, transaction_id, provider_reference, phone_number, details_paiement) 
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)"
        );
        $stmt->execute([$orderId, $amount, $mode, $status, $transactionId, $providerRef, $phone, $details]);
        return $this->pdo->lastInsertId();
    }

    /**
     * Update transaction status
     */
    protected function updateTransactionStatus(string $transactionId, string $status, ?string $rawResponse = null): bool {
        $stmt = $this->pdo->prepare(
            "UPDATE paiements SET statut = ?, raw_response = ?, callback_received = TRUE WHERE transaction_id = ?"
        );
        return $stmt->execute([$status, $rawResponse, $transactionId]);
    }

    /**
     * Make HTTP request using cURL
     */
    protected function makeRequest(string $url, string $method, array $headers, ?array $body = null): array {
        $ch = curl_init($url);

        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_HTTPHEADER => $headers,
            CURLOPT_TIMEOUT => 30,
            CURLOPT_SSL_VERIFYPEER => true,
        ]);

        if ($method === 'POST') {
            curl_setopt($ch, CURLOPT_POST, true);
            if ($body) {
                curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($body));
            }
        }

        $response = curl_exec($ch);
        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        $error = curl_error($ch);
        curl_close($ch);

        return [
            'success' => $httpCode >= 200 && $httpCode < 300,
            'http_code' => $httpCode,
            'body' => json_decode($response, true) ?? $response,
            'error' => $error
        ];
    }

    /**
     * Generate unique reference ID
     */
    protected function generateReferenceId(): string {
        return sprintf('%s-%s', strtoupper(bin2hex(random_bytes(4))), time());
    }
}
