<?php
require_once __DIR__ . '/PaymentGateway.php';

/**
 * MTN Mobile Money (MoMo) Payment Gateway
 * 
 * Flow:
 * 1. Get access token via Basic Auth
 * 2. POST request-to-pay with X-Reference-Id
 * 3. Poll status until SUCCESSFUL/FAILED
 */
class MTNMomoGateway extends PaymentGateway {
    private $subscriptionKey;
    private $userId;
    private $apiKey;
    private $callbackUrl;

    public function __construct(PDO $pdo) {
        parent::__construct($pdo);
        $this->baseUrl = MTN_MOMO_BASE_URL;
        $this->subscriptionKey = MTN_MOMO_SUBSCRIPTION_KEY;
        $this->userId = MTN_MOMO_USER_ID;
        $this->apiKey = MTN_MOMO_API_KEY;
        $this->environment = MTN_MOMO_ENVIRONMENT;
        $this->callbackUrl = MTN_MOMO_CALLBACK_URL;
    }

    /**
     * Get OAuth access token
     */
    private function getAccessToken(): ?string {
        $url = $this->baseUrl . '/collection/token/';
        $credentials = base64_encode($this->userId . ':' . $this->apiKey);

        $headers = [
            'Authorization: Basic ' . $credentials,
            'Ocp-Apim-Subscription-Key: ' . $this->subscriptionKey,
            'Content-Type: application/json'
        ];

        $response = $this->makeRequest($url, 'POST', $headers);

        if ($response['success'] && isset($response['body']['access_token'])) {
            return $response['body']['access_token'];
        }

        error_log('MTN MoMo Token Error: ' . json_encode($response));
        return null;
    }

    /**
     * Initiate a payment request (Request to Pay)
     */
    public function initiatePayment(array $paymentData): array {
        $[REDACTED]
        if (!$token) {
            return ['success' => false, 'error' => 'Failed to obtain access token'];
        }

        $referenceId = $this->generateReferenceId();
        $url = $this->baseUrl . '/collection/v1_0/requesttopay';

        $headers = [
            'Authorization: Bearer ' . $token,
            'X-Reference-Id: ' . $referenceId,
            'X-Target-Environment: ' . $this->environment,
            'Ocp-Apim-Subscription-Key: ' . $this->subscriptionKey,
            'Content-Type: application/json',
            'X-Callback-Url: ' . $this->callbackUrl
        ];

        // Format phone number (remove + and spaces, ensure country code)
        $phone = preg_replace('/[^0-9]/', '', $paymentData['phone']);
        if (strlen($phone) === 9) {
            $phone = '237' . $phone; // Add Cameroon country code
        }

        $body = [
            'amount' => (string) $paymentData['amount'],
            'currency' => 'EUR', // Sandbox uses EUR
            'externalId' => $paymentData['reference'] ?? $referenceId,
            'payer' => [
                'partyIdType' => 'MSISDN',
                'partyId' => $phone
            ],
            'payerMessage' => $paymentData['description'] ?? 'CEKEMA Payment',
            'payeeNote' => 'Order ' . ($paymentData['order_number'] ?? $referenceId)
        ];

        $response = $this->makeRequest($url, 'POST', $headers, $body);

        if ($response['http_code'] === 202) {
            // Request accepted - payment pending
            return [
                'success' => true,
                'transaction_id' => $referenceId,
                'status' => 'PENDING',
                'message' => 'Payment request sent. Please confirm on your phone.',
                'requires_polling' => true
            ];
        }

        return [
            'success' => false,
            'error' => $response['body']['message'] ?? 'Payment initiation failed',
            'details' => $response
        ];
    }

    /**
     * Check payment status
     */
    public function checkStatus(string $transactionId): array {
        $[REDACTED]
        if (!$token) {
            return ['success' => false, 'error' => 'Failed to obtain access token'];
        }

        $url = $this->baseUrl . '/collection/v1_0/requesttopay/' . $transactionId;

        $headers = [
            'Authorization: Bearer ' . $token,
            'X-Target-Environment: ' . $this->environment,
            'Ocp-Apim-Subscription-Key: ' . $this->subscriptionKey
        ];

        $ch = curl_init($url);
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_HTTPHEADER => $headers,
            CURLOPT_TIMEOUT => 30
        ]);

        $response = curl_exec($ch);
        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);

        $data = json_decode($response, true);

        if ($httpCode === 200 && $data) {
            return [
                'success' => true,
                'status' => $data['status'], // PENDING, SUCCESSFUL, FAILED
                'amount' => $data['amount'] ?? null,
                'payer' => $data['payer']['partyId'] ?? null,
                'reason' => $data['reason'] ?? null,
                'raw' => $data
            ];
        }

        return [
            'success' => false,
            'error' => 'Failed to check status',
            'http_code' => $httpCode
        ];
    }

    /**
     * Handle webhook callback
     */
    public function handleCallback(array $callbackData): bool {
        $transactionId = $callbackData['externalId'] ?? $callbackData['referenceId'] ?? null;
        $status = $callbackData['status'] ?? null;

        if (!$transactionId || !$status) {
            error_log('MTN Callback: Missing data - ' . json_encode($callbackData));
            return false;
        }

        $dbStatus = ($status === 'SUCCESSFUL') ? 'complete' : 'echoue';
        return $this->updateTransactionStatus($transactionId, $dbStatus, json_encode($callbackData));
    }
}
