<script>
const transactionId = '<?= htmlspecialchars($transaction_id) ?>';
let pollCount = 0;
const maxPolls = 60; // 5 minutes max (5s intervals)

function checkPaymentStatus() {
    fetch('actions/check_payment_status.php?transaction_id=' + encodeURIComponent(transactionId))
        .then(response => response.json())
        .then(data => {
            pollCount++;

            if (data.status === 'SUCCESSFUL' || data.status === 'complete') {
                document.getElementById('loading-state').style.display = 'none';
                document.getElementById('success-state').style.display = 'block';
            } else if (data.status === 'FAILED' || data.status === 'echoue') {
                document.getElementById('loading-state').style.display = 'none';
                document.getElementById('failed-state').style.display = 'block';
                document.getElementById('error-message').textContent = data.reason || 'Le paiement a été refusé.';
            } else if (pollCount < maxPolls) {
                // Still pending - continue polling
                document.getElementById('status-text').textContent = 
                    'En attente de confirmation... (' + Math.floor(pollCount * 5 / 60) + ' min)';
                setTimeout(checkPaymentStatus, 5000);
            } else {
                // Timeout
                document.getElementById('loading-state').style.display = 'none';
                document.getElementById('failed-state').style.display = 'block';
                document.getElementById('error-message').textContent = 'Délai d\'attente dépassé. Veuillez vérifier votre compte.';
            }
        })
        .catch(err => {
            console.error('Error checking status:', err);
            setTimeout(checkPaymentStatus, 5000);
        });
}

// Start polling after 3 seconds
setTimeout(checkPaymentStatus, 3000);
</script>
