```php
<?php
require_once __DIR__ . '/../config.php';
require_once __DIR__ . '/../includes/payments/PaymentHelper.php';

header('Content-Type: application/json');

if (!isLoggedIn() || !isset($_SESSION['payment_transaction'])) {
    echo json_encode(['error' => 'Unauthorized']);
    exit;
}

$transaction_id = sanitizeInput($_GET['transaction_id'] ?? '');
$stored_transaction = $_SESSION['payment_transaction'];

if ($transaction_id !== $stored_transaction['transaction_id']) {
    echo json_encode(['error' => 'Invalid transaction']);
    exit;
}

// First check database for callback update
$stmt = $pdo->prepare("SELECT statut, raw_response FROM paiements WHERE transaction_id = ?");
$stmt->execute([$transaction_id]);
$payment = $stmt->fetch();

if ($payment && $payment['statut'] !== 'en_attente') {
    // Payment status updated via callback
    if ($payment['statut'] === 'complete') {
        // Update order status
        $stmt = $pdo->prepare("SELECT commande_id FROM paiements WHERE transaction_id = ?");
        $stmt->execute([$transaction_id]);
        $row = $stmt->fetch();
        if ($row) {
            confirmOrderOnPayment($pdo, $row['commande_id']);
        }
        unset($_SESSION['payment_transaction']);
        unset($_SESSION['pending_payment']);
    }

    echo json_encode([
        'status' => $payment['statut'] === 'complete' ? 'SUCCESSFUL' : 'FAILED',
        'source' => 'database'
    ]);
    exit;
}

// If not updated, poll the provider
$gateway = getPaymentGateway($stored_transaction['mode_paiement'], $pdo);
if (!$gateway) {
    echo json_encode(['error' => 'Invalid gateway']);
    exit;
}

$result = $gateway->checkStatus($transaction_id);

if ($result['success']) {
    $status = $result['status'];

    // Update database if status changed
    if ($status === 'SUCCESSFUL') {
        $stmt = $pdo->prepare("UPDATE paiements SET statut = 'complete', raw_response = ? WHERE transaction_id = ?");
        $stmt->execute([json_encode($result['raw'] ?? []), $transaction_id]);

        confirmOrderOnPayment($pdo, $stored_transaction['commande_id']);
        unset($_SESSION['payment_transaction']);
        unset($_SESSION['pending_payment']);

    } elseif ($status === 'FAILED') {
        $stmt = $pdo->prepare("UPDATE paiements SET statut = 'echoue', raw_response = ? WHERE transaction_id = ?");
        $stmt->execute([json_encode($result['raw'] ?? []), $transaction_id]);
    }

    echo json_encode([
        'status' => $status,
        'reason' => $result['reason'] ?? null
    ]);
} else {
    echo json_encode(['status' => 'PENDING', 'error' => $result['error'] ?? null]);
}
