const API_V3_URL = 'https://gateway.awdpay.com';

exports.mtnPayment = async (data, user, number, payment_method, country, return_url, cancel_url) => {
  const Log = db.logs;
  try {
    // Extraction robuste du code pays
    let countryCode = null;
    if (country) {
      if (typeof country === 'string') {
        countryCode = country.toUpperCase();
      } else if (country.code) {
        countryCode = country.code.toUpperCase();
      } else if (country.value) {
        countryCode = country.value.toUpperCase();
      }
    }

    await Log.create({
      message: `MTN Payment Init: method=${payment_method}, countryCode=${countryCode}, number=${number}, depositId=${data.id}, country=${JSON.stringify(country)}`,
    });

    if (!countryCode) {
      await Log.create({ message: `MTN Payment Error: Country code is null or invalid. Received: ${JSON.stringify(country)}` });
      throw new Error('Country code is required for MTN payment');
    }

    const gatewayFind = await Gateway.findOne({ where: { value: 'mtn' } });
    if (!gatewayFind) {
      await Log.create({ message: 'MTN Payment Error: MTN Gateway not found in database' });
      throw new Error('MTN Gateway configuration not found in database');
    }

    const appUrl = await Setting.findOne({ where: { value: 'appUrl' } });
    const reference = uuid.v4();

    let parsedVariables;
    try {
      parsedVariables = JSON.parse(gatewayFind.variables);
    } catch (parseErr) {
      await Log.create({ message: `MTN Payment Error: Failed to parse gateway variables - ${parseErr.message}` });
      throw new Error('Invalid MTN gateway configuration');
    }

    const variables = parsedVariables[countryCode];

    if (!variables) {
      const availableCountries = Object.keys(parsedVariables).join(', ');
      await Log.create({
        message: `MTN Payment Error: No config for ${countryCode}. Available: ${availableCountries}`,
      });
      throw new Error(`MTN is not configured for country: ${countryCode}. Available countries: ${availableCountries}`);
    }

    if (!variables.collection) {
      await Log.create({ message: `MTN Payment Error: Collection config missing for ${countryCode}` });
      throw new Error(`MTN Collection not configured for country: ${countryCode}`);
    }

    const gateway = variables.collection;
    console.log('\x1b[31m', 'MTN Initiation for :', countryCode, '\x1b[0m');
    const baseURL = 'https://proxy.momoapi.mtn.com';

    await Log.create({
      message: `MTN Auth attempt for ${countryCode}: apiKey=${gateway.apiKey ? gateway.apiKey.substring(0, 8) + '...' : 'MISSING'}, env=${variables.env}`,
    });

    let accessData;
    try {
      accessData = await rp({
        method: 'POST',
        uri: `${baseURL}/collection/token/`,
        json: true,
        auth: {
          user: gateway.apiKey,
          pass: gateway.secretKey,
        },
        headers: {
          Accept: 'application/json',
          'Ocp-Apim-Subscription-Key': gateway.ex1,
        },
      });
      await Log.create({ message: `MTN Auth Success for ${countryCode}` });
    } catch (authErr) {
      const errorDetail = authErr.error ? JSON.stringify(authErr.error) : authErr.message;
      await Log.create({
        message: `MTN Auth Failed (${countryCode}): ${errorDetail} - StatusCode: ${authErr.statusCode || 'N/A'}`,
      });
      throw new Error(`MTN authentication failed for ${countryCode}: ${authErr.message}`);
    }

    const requesttopay = await rp({
      method: 'POST',
      uri: `${baseURL}/collection/v1_0/requesttopay`,
      json: true,
      body: {
        amount: `${data.amount}`,
        currency: `${data.currency}`,
        externalId: `${data.id}`,
        payer: {
          partyIdType: 'MSISDN',
          partyId: number,
        },
        payerMessage: 'AWDPAY Deposit Request',
        payeeNote: 'AWDPAY Deposit Request',
      },
      headers: {
        Accept: 'application/json',
        Authorization: `Bearer ${accessData.access_token}`,
        'Ocp-Apim-Subscription-Key': gateway.ex1,
        'X-Target-Environment': variables.env,
        'X-Reference-Id': reference,
        // 'X-Callback-Url': `${appUrl.param1}/api/payments/verifymtn`,
      },
    });

    const Deposit = db.deposits;
    const Request = db.requests;

    let validated = false;

    const checkInterval = setInterval(async () => {
      let transaction;
      try {
        const response = await rp({
          method: 'GET',
          uri: `${baseURL}/collection/v1_0/requesttopay/${reference}`,
          json: true,
          headers: {
            Accept: 'application/json',
            Authorization: `Bearer ${accessData.access_token}`,
            'Ocp-Apim-Subscription-Key': gateway.ex1,
            'X-Target-Environment': variables.env,
            'X-Reference-Id': reference,
          },
        });

        await Log.create({ message: `check if well register in mtn (ref: ${reference})` });

        if (response.status === 'SUCCESSFUL') {
          transaction = await db.sequelize.transaction();
          const depositData = await Deposit.findByPk(data.id, {
            lock: transaction.LOCK.UPDATE,
            transaction,
          });

          if (depositData.status !== 'pending') {
            await transaction.commit();
            clearInterval(checkInterval);
            validated = true;
            return;
          }

          const balanceResult = await addBalance(depositData.depositAmount, depositData.currency, depositData.userId, 12, { transaction }, `Dépôt #${depositData.id} via MTN`);
          if (balanceResult.error) {
            await Log.create({ message: `MTN deposit #${depositData.id} - addBalance failed: ${balanceResult.error}` }, { transaction });
            await notifyAddBalanceError('Deposit MTN', depositData.id, depositData.depositAmount, depositData.currency, depositData.userId, balanceResult.error);
            throw new Error(`Failed to add balance: ${balanceResult.error}`);
          }

          await Deposit.update({ payment_status: true, status: 'success' }, {
            where: { id: depositData.id },
            transaction,
          });
          await Request.update({ status: 'success' }, {
            where: {
              depotAndWithdrawID: depositData.id,
              type: 'deposit',
            },
            transaction,
          });
          await Log.create({ message: `MTN confirmed payment for deposit #${depositData.id} (ref: ${reference})` }, { transaction });

          await transaction.commit();

          firstDeposit(depositData.id);
          validated = true;
          clearInterval(checkInterval);
          await notifyWebhook(depositData.id);
          await Log.create({ message: `is validated from mtn (ref: ${reference})` });
        }
      } catch (err) {
        if (transaction) await transaction.rollback();
      }
    }, 30000);

    setTimeout(async () => {
      if (validated) return;
      let transaction;
      try {
        transaction = await db.sequelize.transaction();
        const depositData = await Deposit.findByPk(data.id, {
          lock: transaction.LOCK.UPDATE,
          transaction,
        });

        clearInterval(checkInterval);
        if (depositData.status === 'pending') {
          await Deposit.update({ payment_status: false, status: 'failed' }, {
            where: { id: depositData.id },
            transaction,
          });
          await Request.update({ status: 'failed' }, {
            where: {
              depotAndWithdrawID: depositData.id,
              type: 'deposit',
            },
            transaction,
          });
          await Log.create({ message: `MTN declined payment for deposit #${depositData.id} (ref: ${reference})` }, { transaction });
          await transaction.commit();
        } else {
          await transaction.commit();
        }
      } catch (err) {
        if (transaction) await transaction.rollback();
      }
      await notifyWebhook(data.id);
      // firstDeposit(depositData.id);
    }, 360000);

    return return_url || '/add-money?status=success';
  } catch (err) {
    console.error(err);
    const Log = db.logs;
    await Log.create({ message: err.message || err.toString() });
    return cancel_url || '/add-money?status=failed';
  }
};

exports.creditMtnPayment = async (data) => {
  const Log = db.logs;
  const gatewayFind = await Gateway.findOne({ where: { value: 'mtn' } });
  try {
    const appUrl = await Setting.findOne({ where: { value: 'appUrl' } });
    const reference = uuid.v4();
    const countryCode = data.country ? (typeof data.country === 'string' ? data.country.toUpperCase() : (data.country.code ? data.country.code.toUpperCase() : null)) : null;
    const t = JSON.parse(gatewayFind.variables);
    const variables = t[countryCode];
    const gateway = variables.disbursement;

    const baseURL = 'https://proxy.momoapi.mtn.com';

