    await Log.create({
      message: `withdraw success register in mtn (ref: ${reference})  amount : ${data.amount}
    currency: ${data.currency}
    externalId: ${data.id}, data.number : ${data.number}`,
    });

    const Withdraw = db.withdraws;
    const Request = db.requests;
    let validated = false;

    const checkInterval = setInterval(async () => {
      let transaction;
      try {
        const response = await rp({
          method: 'GET',
          uri: `${baseURL}/disbursement/v1_0/transfer/${reference}`,
          json: true,
          headers: {
            Accept: 'application/json',
            Authorization: `Bearer ${accessData.access_token}`,
            'Ocp-Apim-Subscription-Key': gateway.ex1,
            'X-Target-Environment': variables.env,
            'X-Reference-Id': reference,
          },
        });
        await Log.create({
          message: `check if well register in mtn (ref: ${reference}) amount : ${data.amount}
        currency: ${data.currency}
        externalId: ${data.id} message erreur ${response.reason} message ${response.message}`,
        });

        console.log({ response });
        if (response.status === 'SUCCESSFUL') {
          // Note: Withdraw success updates are usually less critical for double-spend (since user gets money OUT),
          // but good to lock to avoid double confirmation logging/notifying.
          transaction = await db.sequelize.transaction();
          const withdrawData = await Withdraw.findByPk(data.id, { lock: transaction.LOCK.UPDATE, transaction });

          if (withdrawData.status !== 'pending') {
            await transaction.commit();
            clearInterval(checkInterval);
            validated = true;
            return;
          }

          await Withdraw.update({ status: 'success' }, { where: { id: withdrawData.id }, transaction });

          // Non-bloquant: notification gateway
          rp({
            method: 'POST',
            uri: `${API_V3_URL}/webhook/payout`,
            json: true,
            body: {
              status: 'success',
