        clearInterval(checkInterval);
        if (withdrawData.status === 'pending') {
          const balanceResult = await addBalance(withdrawData.amount, withdrawData.currency, withdrawData.userId, 12, { transaction }, `Remboursement withdraw #${withdrawData.id} - timeout MTN`);
          if (balanceResult.error) {
            await Log.create({ message: `MTN withdraw #${withdrawData.id} - refund addBalance failed: ${balanceResult.error}` }, { transaction });
            await notifyAddBalanceError('Withdraw MTN Refund', withdrawData.id, withdrawData.amount, withdrawData.currency, withdrawData.userId, balanceResult.error);
            throw new Error(`Failed to refund balance: ${balanceResult.error}`);
          }
          await Withdraw.update({ payment_status: false, status: 'failed' }, {
            where: { id: withdrawData.id },
            transaction,
          });

          // Non-bloquant: notification gateway
          rp({
            method: 'POST',
            uri: `${API_V3_URL}/webhook/payout`,
            json: true,
            body: {
              status: 'failed',
              withdrawId: withdrawData.id,
            },
          }).catch((err) => Log.create({ message: `Gateway payout notification failed: ${err.message}` }));

          await Request.update({ status: 'failed' },
            { where: { depotAndWithdrawID: withdrawData.id, type: 'withdraw' }, transaction });

          await Log.create({ message: `MTN declined payment for withdraw #${withdrawData.id} (ref: ${reference})` }, { transaction });
          await transaction.commit();
        } else {
          await transaction.commit();
        }
      } catch (err) {
        if (transaction) await transaction.rollback();
      }
    }, 360000);

    return 'pending';
  } catch (err) {
    return 'error';
  }
};

