            'error' => 'Failed to check status',
            'http_code' => $httpCode
        ];
    }

    /**
     * Handle notification callback (POST from Orange)
     */
    public function handleCallback(array $callbackData): bool {
        $orderId = $callbackData['order_id'] ?? null;
        $status = $callbackData['status'] ?? null;

        if (!$orderId || !$status) {
            error_log('Orange Callback: Missing data - ' . json_encode($callbackData));
            return false;
        }

        // Map Orange status to internal status
        $statusMap = [
            'SUCCESS' => 'complete',
            'SUCCESSFULL' => 'complete',
            'FAILED' => 'echoue',
            'EXPIRED' => 'echoue'
        ];

        $dbStatus = $statusMap[strtoupper($status)] ?? 'en_attente';
        return $this->updateTransactionStatus($orderId, $dbStatus, json_encode($callbackData));
    }
