/**
 * Payment Helper Functions
 */

/**
 * Get the appropriate gateway instance
 */
function getPaymentGateway(string $method, PDO $pdo): ?PaymentGateway {
    require_once __DIR__ . '/MTNMomoGateway.php';
    require_once __DIR__ . '/OrangeMoneyGateway.php';

    switch ($method) {
