        case 'mtn_money':
            return new MTNMomoGateway($pdo);
        case 'orange_money':
            return new OrangeMoneyGateway($pdo);
        default:
            return null;
    }
}

/**
 * Update order payment status
 */
function updateOrderPaymentStatus(PDO $pdo, int $orderId, string $status): bool {
    $stmt = $pdo->prepare("UPDATE commandes SET statut_paiement = ?, date_paiement = NOW() WHERE id = ?");
    return $stmt->execute([$status, $orderId]);
}

/**
 * Update order status to confirmed when paid
 */
function confirmOrderOnPayment(PDO $pdo, int $orderId): bool {
    $stmt = $pdo->prepare("UPDATE commandes SET statut = 'confirmee', statut_paiement = 'paye', date_paiement = NOW() WHERE id = ?");
    return $stmt->execute([$orderId]);
}

/**
 * Format phone number for Cameroon
 */
function formatCameroonPhone(string $phone): string {
    $phone = preg_replace('/[^0-9]/', '', $phone);
    if (strlen($phone) === 9 && ($phone[0] === '6' || $phone[0] === '2')) {
        return '237' . $phone;
    }
    return $phone;
}

/**
 * Validate Cameroon phone number
 */
function isValidCameroonPhone(string $phone): bool {
    $phone = preg_replace('/[^0-9]/', '', $phone);
    // 9 digits starting with 6 (mobile) or 2 (fixed)
    // Or 12 digits with 237 prefix
    return preg_match('/^(237)?(6[5-9]\d{7}|2[2-3]\d{7})$/', $phone);
}
