```php
<?php
/**
 * Payment Callback Handler
 * Receives webhooks from MTN MoMo and Orange Money
 */
require_once __DIR__ . '/../config.php';
require_once __DIR__ . '/../functions.php';
require_once __DIR__ . '/../includes/payments/PaymentHelper.php';

// Log all incoming callbacks
$rawInput = file_get_contents('php://input');
$headers = getallheaders();
error_log('Payment Callback - Headers: ' . json_encode($headers));
error_log('Payment Callback - Body: ' . $rawInput);

$data = json_decode($rawInput, true);
if (!$data) {
    $data = $_POST;
}

// Determine provider based on request characteristics
$provider = null;

// MTN MoMo typically includes externalId or uses specific headers
if (isset($data['externalId']) || isset($data['referenceId']) || isset($headers['X-Reference-Id'])) {
    $provider = 'mtn_momo';
}
// Orange Money includes order_id and specific status codes
elseif (isset($data['order_id']) || isset($data['txnid'])) {
    $provider = 'orange_money';
}

if (!$provider) {
    error_log('Payment Callback - Unknown provider');
    http_response_code(400);
    exit;
}

try {
    $gateway = getPaymentGateway($provider, $pdo);

    if ($gateway && $gateway->handleCallback($data)) {
        // Get transaction info
        $transactionId = $data['externalId'] ?? $data['referenceId'] ?? $data['order_id'] ?? null;

        if ($transactionId) {
            $stmt = $pdo->prepare("SELECT commande_id, statut FROM paiements WHERE transaction_id = ?");
            $stmt->execute([$transactionId]);
            $payment = $stmt->fetch();

            if ($payment && $payment['statut'] === 'complete') {
                // Update order status
                confirmOrderOnPayment($pdo, $payment['commande_id']);

                // Send notifications
                $stmt = $pdo->prepare("SELECT user_id, numero_commande FROM commandes WHERE id = ?");
                $stmt->execute([$payment['commande_id']]);
                $order = $stmt->fetch();

                if ($order) {
                    pushToUsers(
                        [$order['user_id']],
                        "Paiement confirmé",
                        "Votre paiement pour la commande {$order['numero_commande']} a été reçu."
                    );
                }
            }
        }

        http_response_code(200);
        echo json_encode(['status' => 'OK']);
    } else {
        http_response_code(400);
        echo json_encode(['status' => 'ERROR']);
    }
} catch (Exception $e) {
    error_log('Payment Callback Error: ' . $e->getMessage());
    http_response_code(500);
}
