<?php
require_once '../config.php';
require_once '../includes/payments/PaymentHelper.php';

// AJAX status check
if (isset($_GET['action']) && $_GET['action'] === 'check') {
    header('Content-Type: application/json');

    $transaction_id = sanitizeInput($_GET['transaction_id'] ?? '');

    if (!$transaction_id) {
        echo json_encode(['error' => 'Missing transaction ID']);
        exit;
    }

    // Check database first
    $stmt = $pdo->prepare("SELECT statut FROM paiements_abonnement WHERE transaction_id = ?");
    $stmt->execute([$transaction_id]);
    $payment = $stmt->fetch();

    if ($payment && $payment['statut'] !== 'en_attente') {
        echo json_encode(['status' => $payment['statut'] === 'complete' ? 'SUCCESSFUL' : 'FAILED']);
        exit;
    }

    // Poll provider
    $gateway = getPaymentGateway('mtn_momo', $pdo);
    $result = $gateway->checkStatus($transaction_id);

    if ($result['success']) {
        $status = $result['status'];

        if ($status === 'SUCCESSFUL') {
            // Activate subscription
            $stmt = $pdo->prepare("UPDATE paiements_abonnement SET statut = 'complete', raw_response = ? WHERE transaction_id = ?");
            $stmt->execute([json_encode($result), $transaction_id]);

            // Calculate subscription dates
            $stmt = $pdo->prepare("SELECT vendeur_id, plan_nom, duree FROM paiements_abonnement WHERE transaction_id = ?");
            $stmt->execute([$transaction_id]);
            $sub = $stmt->fetch();

            if ($sub) {
                $durationMonths = ['Mensuel' => 1, 'Trimestriel' => 3, 'Semestriel' => 6, 'Annuel' => 12];
                $months = $durationMonths[$sub['duree']] ?? 1;
                $dateDebut = date('Y-m-d');
                $dateFin = date('Y-m-d', strtotime("+$months months"));

                $stmt = $pdo->prepare("UPDATE paiements_abonnement SET date_debut = ?, date_fin = ? WHERE transaction_id = ?");
                $stmt->execute([$dateDebut, $dateFin, $transaction_id]);

                // Update user status
                $stmt = $pdo->prepare("UPDATE users SET status = 'actif' WHERE id = ?");
                $stmt->execute([$sub['vendeur_id']]);
            }
        } elseif ($status === 'FAILED') {
            $stmt = $pdo->prepare("UPDATE paiements_abonnement SET statut = 'echoue', raw_response = ? WHERE transaction_id = ?");
            $stmt->execute([json_encode($result), $transaction_id]);
        }

        echo json_encode(['status' => $status]);
    } else {
        echo json_encode(['status' => 'PENDING']);
    }
    exit;
}

// Orange Money return handler
if (isset($_GET['order_id'])) {
    $order_id = sanitizeInput($_GET['order_id']);

    $gateway = getPaymentGateway('orange_money', $pdo);
    $result = $gateway->checkStatus($order_id);

    if ($result['success'] && in_array($result['status'], ['SUCCESS', 'SUCCESSFULL'])) {
        // Update subscription
        $stmt = $pdo->prepare("UPDATE paiements_abonnement SET statut = 'complete', raw_response = ? WHERE transaction_id = ?");
        $stmt->execute([json_encode($result), $order_id]);

        // Activate subscription (same logic as above)
        // ...

        flashMessage('success', 'Votre abonnement a été activé avec succès !');
    } else {
        flashMessage('error', 'Le paiement n\'a pas pu être confirmé.');
    }

    redirect('index.php');
}
