   152→        $walletService = new WalletService($pdo);
   153→
   154→        // Récupérer les items de la commande groupés par vendeur
   155→        $stmt = $pdo->prepare("
   156→            SELECT vendeur_id, SUM(sous_total) as total_vendeur
   157→            FROM commande_items
   158→            WHERE commande_id = ?
   159→            GROUP BY vendeur_id
   160→        ");
   161→        $stmt->execute([$commandeId]);
   162→        $ventesParVendeur = $stmt->fetchAll(PDO::FETCH_ASSOC);
   163→
   164→        foreach ($ventesParVendeur as $vente) {
