   229→ * @param int|null $userId ID utilisateur (par défaut l'utilisateur connecté)
   230→ * @return array ['active' => bool, 'subscription' => array|null, 'expires_in' => int|null]
   231→ */
   232→function checkVendorSubscription($userId = null)
   233→{
   234→    global $pdo;
   235→
   236→    if ($userId === null) {
   237→        $userId = getUserId();
   238→    }
   239→
   240→    if (!$userId) {
   241→        return ['active' => false, 'subscription' => null, 'expires_in' => null];
   242→    }
   243→
   244→    // Chercher un abonnement actif
   245→    $stmt = $pdo->prepare("
   246→        SELECT *
   247→        FROM paiements_abonnement
   248→        WHERE vendeur_id = ?
   249→        AND statut = 'complete'
   250→        AND (date_fin IS NULL OR date_fin >= CURDATE())
   251→        ORDER BY date_fin DESC
   252→        LIMIT 1
   253→    ");
   254→    $stmt->execute([$userId]);
   255→    $subscription = $stmt->fetch(PDO::FETCH_ASSOC);
   256→
   257→    if ($subscription) {
   258→        $expiresIn = null;
   259→        if ($subscription['date_fin']) {
   260→            $expiresIn = (strtotime($subscription['date_fin']) - time()) / 86400; // jours restants
   261→        }
   262→
   263→        return [
   264→            'active' => true,
   265→            'subscription' => $subscription,
   266→            'expires_in' => $expiresIn ? round($expiresIn) : null
   267→        ];
   268→    }
   269→
   270→    return ['active' => false, 'subscription' => null, 'expires_in' => null];
   271→}
