     5→/**
     6→ * Analyse audio PCM 16-bit pour détecter parole/silence et fin de tour.
     7→ *
     8→ * Utilise le RMS (Root Mean Square) pour mesurer l'énergie du signal :
     9→ * - Silence : RMS < 500
    10→ * - Parole  : RMS > 500
    11→ *
    12→ * IMPORTANT : Nécessite de l'audio PCM brut (non compressé).
    13→ * Les formats compressés (Opus, MP3, AAC) doivent être décodés avant analyse.
    14→ */
    15→public class VoiceActivityDetector {
    16→
    17→    private static final double SPEECH_THRESHOLD_RMS = 500.0;
    18→    private static final long SILENCE_THRESHOLD_MS = 1500;
    19→
    20→    public VadResult analyze(AudioData audioData, VadState currentState) {
    21→        double rms = computeRms(audioData.rawData());
    22→        boolean speechDetected = rms > SPEECH_THRESHOLD_RMS;
    23→
    24→        long consecutiveSilenceMs;
    25→        long totalSpeechDurationMs = currentState.totalSpeechDurationMs();
    26→
    27→        if (speechDetected) {
    28→            consecutiveSilenceMs = 0;
    29→            totalSpeechDurationMs += audioData.durationMs();
    30→        } else {
    31→            consecutiveSilenceMs = currentState.consecutiveSilenceMs() + audioData.durationMs();
    32→        }
    33→
    34→        boolean turnEnded = consecutiveSilenceMs >= SILENCE_THRESHOLD_MS && totalSpeechDurationMs > 0;
    35→
    36→        return new VadResult(speechDetected, turnEnded, consecutiveSilenceMs, totalSpeechDurationMs);
    37→    }
    38→
    39→    /**
    40→     * Calcule le RMS (Root Mean Square) d'un signal PCM 16-bit little-endian.
    41→     *
    42→     * PCM 16-bit : chaque échantillon = 2 bytes, valeurs de -32768 à +32767
    43→     * RMS = √(Σ(sample²) / n)
    44→     */
    45→    private double computeRms(byte[] rawData) {
    46→        if (rawData == null || rawData.length < 2) return 0.0;
    47→
    48→        long sumSquares = 0;
    49→        int sampleCount = rawData.length / 2;
    50→
    51→        for (int i = 0; i < rawData.length - 1; i += 2) {
    52→            // Little-endian : byte[i] = low byte, byte[i+1] = high byte
    53→            short sample = (short) ((rawData[i + 1] << 8) | (rawData[i] & 0xFF));
    54→            sumSquares += (long) sample * sample;
    55→        }
    56→
    57→        return Math.sqrt((double) sumSquares / sampleCount);
    58→    }
