    36→     * @return AudioData normalisé en PCM 16kHz
    37→     * @throws InvalidAudioFormatException si le format n'est pas supporté
    38→     */
    39→    public AudioData validate(byte[] rawData, String filename) {
    40→        // Vérifications de base
    41→        if (rawData == null || rawData.length == 0) {
    42→            throw new InvalidAudioFormatException("Audio data is empty");
    43→        }
    44→        if (rawData.length > MAX_CHUNK_SIZE_BYTES) {
    45→            throw new InvalidAudioFormatException(
    46→                    String.format("Audio chunk exceeds maximum size of 1MB (received: %d bytes)", rawData.length));
    47→        }
    48→
    49→        // Validation et détection du format
    50→        AudioFormatValidator.ValidationResult result = formatValidator.validate(rawData, filename);
    51→
    52→        if (!result.valid()) {
    53→            throw new InvalidAudioFormatException(result.error(), result.formatName());
    54→        }
    55→
    56→        // Normalisation vers PCM 16kHz 16-bit
    57→        return switch (result.detectedFormat()) {
    58→            case PCM_16BIT -> new AudioData(rawData, AudioFormat.pcm16kMono());
    59→            case ALAW -> convertAlawToPcm(rawData);
