   136→    @Cacheable(value = "suggest", key = "#keyword + #tlds.toString()")
   137→    public SuggestAlternativesResponse suggestAlternatives(String keyword, List<String> tlds, int count) {
   138→        log.debug("Suggesting alternatives for: {}", keyword);
   139→
   140→        List<String> variations = List.of(
   141→            keyword,
   142→            "get" + keyword,
   143→            keyword + "hq",
