   159→        for (SearchDomainsResponse.DomainResultDto result : searchResult.getResults()) {
   160→            if (result.isAvailable()) {
   161→                suggestions.add(SuggestAlternativesResponse.SuggestionDto.builder()
   162→                    .rank(rank++)
   163→                    .domain(result.getDomain())
   164→                    .relevanceScore(calculateRelevance(keyword, result.getDomain()))
   165→                    .available(true)
   166→                    .price(result.getPrice())
   167→                    .registrar(result.getRegistrar())
   168→                    .affiliateLink(result.getAffiliateLink())
   169→                    .build());
   170→
   171→                if (suggestions.size() >= count) {
   172→                    break;
   173→                }
   174→            }
   175→        }
   176→
   177→        // Sort by relevance score
   178→        suggestions.sort(Comparator.comparing(SuggestAlternativesResponse.SuggestionDto::getRelevanceScore).reversed());
   179→
   180→        // Reassign ranks after sorting
   181→        for (int i = 0; i < suggestions.size(); i++) {
   182→            suggestions.get(i).setRank(i + 1);
   183→        }
   184→
   185→        return SuggestAlternativesResponse.builder()
   186→            .keyword(keyword)
   187→            .suggestions(suggestions)
   188→            .total(suggestions.size())
   189→            .tips(List.of(
   190→                "Consider .io for tech/startup brands",
   191→                "Adding 'get', 'try', or 'use' prefix keeps the brand recognizable",
   192→                "Shorter domains are easier to remember and type"
   193→            ))
   194→            .build();
   195→    }
   196→
   197→    // Helper methods
   198→
   199→    private List<String> generateSuggestions(List<String> keywords) {
   200→        List<String> suggestions = new ArrayList<>();
   201→        for (String keyword : keywords) {
   202→            suggestions.add(keyword + "lab.com");
   203→            suggestions.add("my" + keyword + ".io");
   204→            suggestions.add(keyword + "zone.com");
   205→        }
   206→        return suggestions;
   207→    }
   208→
   209→    private double calculateRelevance(String keyword, String domain) {
   210→        String name = domain.split("\\.")[0];
   211→        if (name.equals(keyword)) return 1.0;
   212→        if (name.startsWith(keyword)) return 0.9;
   213→        if (name.endsWith(keyword)) return 0.8;
   214→        if (name.contains(keyword)) return 0.7;
   215→        return 0.5;
   216→    }
   217→}
