package com.cdomain.mcp.config;

import com.fasterxml.jackson.databind.ObjectMapper;
import io.modelcontextprotocol.server.McpServer;
import io.modelcontextprotocol.server.McpSyncServer;
import io.modelcontextprotocol.server.transport.StdioServerTransportProvider;
import io.modelcontextprotocol.spec.McpSchema.ServerCapabilities;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;

@Configuration
@Profile("mcp")
public class McpServerConfig {

    @Bean
    public ObjectMapper mcpObjectMapper() {
        return new ObjectMapper();
    }

    @Bean
    public StdioServerTransportProvider stdioTransportProvider(ObjectMapper objectMapper) {
        return new StdioServerTransportProvider(objectMapper);
    }

    @Bean
    public McpSyncServer mcpServer(
            StdioServerTransportProvider transportProvider,
            DomainToolProvider toolProvider) {

        McpSyncServer server = McpServer.sync(transportProvider)
            .serverInfo("cdomain-mcp", "1.0.0")
            .capabilities(ServerCapabilities.builder()
                .tools(true)
                .build())
            .build();

        // Register all domain tools
        toolProvider.registerTools(server);

        return server;
    }
}
```

