package com.cdomain.mcp.tools;

import com.cdomain.dto.response.SearchDomainsResponse;
import com.cdomain.service.DomainService;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.modelcontextprotocol.server.McpServerFeatures.SyncToolSpecification;
import io.modelcontextprotocol.spec.McpSchema.CallToolResult;
import io.modelcontextprotocol.spec.McpSchema.TextContent;
import io.modelcontextprotocol.spec.McpSchema.Tool;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Component;

import java.util.List;

@Component
@RequiredArgsConstructor
public class SearchDomainsTool {

    private final DomainService domainService;
    private final ObjectMapper objectMapper;

    private static final String SCHEMA = """
        {
            "type": "object",
            "properties": {
                "keywords": {
                    "type": "array",
                    "items": { "type": "string" },
                    "description": "List of keywords to search for domain names"
                },
                "tlds": {
                    "type": "array",
                    "items": { "type": "string" },
                    "description": "Optional list of TLDs to search (e.g., ['.com', '.io', '.ai']). Defaults to common TLDs."
                },
                "maxResults": {
                    "type": "integer",
                    "description": "Maximum number of results to return. Defaults to 20.",
                    "default": 20
                }
            },
            "required": ["keywords"]
        }
        """;

    @SuppressWarnings("unchecked")
    public SyncToolSpecification getSpecification() {
        return new SyncToolSpecification(
            new Tool(
                "search-domains",
                "Search for available domain names based on keywords. Returns a list of available domains with pricing information.",
                SCHEMA
            ),
            (exchange, arguments) -> {
                List<String> keywords = (List<String>) arguments.get("keywords");
                List<String> tlds = arguments.containsKey("tlds") 
                    ? (List<String>) arguments.get("tlds")
                    : List.of(".com", ".net", ".org", ".io", ".co", ".ai", ".dev");
                int maxResults = arguments.containsKey("maxResults")
                    ? ((Number) arguments.get("maxResults")).intValue()
                    : 20;

                try {
                    SearchDomainsResponse response = domainService.searchDomains(keywords, tlds, maxResults);
