```java
package com.cdomain.mcp.tools;

import com.cdomain.dto.response.CheckAvailabilityResponse;
import com.cdomain.dto.response.RegistrarResultDto;
import com.cdomain.service.DomainService;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.modelcontextprotocol.spec.McpSchema;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Slf4j
@Component
@RequiredArgsConstructor
public class CheckAvailabilityTool {

    public static final String TOOL_NAME = "check-availability";

    private final DomainService domainService;
    private final ObjectMapper objectMapper;

    public McpSchema.Tool getToolDefinition() {
        return new McpSchema.Tool(
            TOOL_NAME,
            "Check if a domain name is available for registration. Returns availability status, pricing, and purchase links.",
            buildInputSchema()
        );
    }

    private McpSchema.JsonSchema buildInputSchema() {
        Map<String, Object> properties = new HashMap<>();
        Map<String, Object> domainProp = new HashMap<>();
        domainProp.put("type", "string");
        domainProp.put("description", "The domain name to check (e.g., 'example.com')");
        properties.put("domain", domainProp);

        return new McpSchema.JsonSchema(
            "object",
            properties,
            List.of("domain"),
            false
        );
    }

    public McpSchema.CallToolResult handle(Map<String, Object> arguments) {
        String domain = (String) arguments.get("domain");
        if (domain == null || domain.isBlank()) {
            return createErrorResult("Missing required parameter: domain");
        }
        try {
            CheckAvailabilityResponse response = domainService.checkAvailability(domain);
            return createSuccessResult(response);
        } catch (Exception e) {
            log.error("Error checking availability for domain: {}", domain, e);
            return createErrorResult("Error checking availability: " + e.getMessage());
        }
    }

    private McpSchema.CallToolResult createSuccessResult(CheckAvailabilityResponse response) {
        StringBuilder text = new StringBuilder();
        text.append("Domain: ").append(response.getDomain()).append("\n");
        text.append("Available: ").append(response.isAvailable() ? "Yes" : "No").append("\n");
        // ... formatting code for registrars and recommendations
        return new McpSchema.CallToolResult(
            List.of(new McpSchema.TextContent(text.toString())),
            false
        );
    }

    private McpSchema.CallToolResult createErrorResult(String message) {
        return new McpSchema.CallToolResult(
            List.of(new McpSchema.TextContent("Error: " + message)),
            true
        );
    }
}
```

