    13→/**
    14→ * Core service for domain search and discovery operations.
    15→ *
    16→ * <p>Provides domain availability checking and search features
    17→ * using Porkbun as the sole registrar provider.
    18→ *
    19→ * <p><b>Caching:</b> Results are cached with Spring Cache:
    20→ * <ul>
    21→ *   <li>"availability" - Domain availability checks (TTL: 5 min)</li>
    22→ *   <li>"search" - Search results (TTL: 10 min)</li>
    23→ * </ul>
    24→ *
    25→ * @author CDomain Team
    26→ * @version 2.0.0
    27→ * @see PorkbunAdapter
    28→ */
    29→@Slf4j
    30→@Service
    31→@RequiredArgsConstructor
    32→public class DomainService {
    33→
    34→    private final PorkbunAdapter porkbunAdapter;
    35→
    36→    /**
    37→     * Checks domain availability via Porkbun.
    38→     *
    39→     * @param domain the domain name to check (normalized to lowercase)
    40→     * @return CheckAvailabilityResponse with availability and pricing
    41→     */
    42→    @Cacheable(value = "availability", key = "#domain")
    43→    public CheckAvailabilityResponse checkAvailability(String domain) {
    44→        domain = domain.toLowerCase();
    45→        log.debug("Checking availability for: {}", domain);
    46→
    47→        if (!porkbunAdapter.isAvailable()) {
    48→            log.warn("Porkbun adapter not configured");
    49→            return CheckAvailabilityResponse.builder()
    50→                .domain(domain)
    51→                .available(false)
    52→                .registrars(List.of())
    53→                .build();
    54→        }
    55→
    56→        DomainAvailability result = porkbunAdapter.checkAvailability(domain);
    57→
    58→        RegistrarResultDto registrarResult = RegistrarResultDto.builder()
    59→            .name(porkbunAdapter.getName())
    60→            .available(result.isAvailable())
    61→            .premium(result.isPremium())
    62→            .price(result.getPrice() != null ? DomainPriceDto.from(
    63→                result.getPrice().getRegistration(),
    64→                result.getPrice().getRenewal(),
    65→                result.getPrice().getTransfer()
    66→            ) : null)
    67→            .affiliateLink(porkbunAdapter.getAffiliateLink(domain))
    68→            .build();
    69→
    70→        return CheckAvailabilityResponse.builder()
    71→            .domain(domain)
    72→            .available(result.isAvailable())
    73→            .registrars(List.of(registrarResult))
    74→            .recommendation(CheckAvailabilityResponse.RecommendationDto.builder()
    75→                .bestValue("Porkbun")
    76→                .reason("Free WHOIS Privacy and SSL included")
    77→                .build())
    78→            .build();
    79→    }
    80→
    81→    /**
    82→     * Searches for available domains based on keywords and TLDs.
    83→     *
    84→     * @param keywords list of keywords to combine with TLDs
    85→     * @param tlds list of TLDs to search (with or without leading dot)
    86→     * @param maxResults maximum number of results to return
    87→     * @return SearchDomainsResponse with available domains
    88→     */
    89→    @Cacheable(value = "search", key = "#keywords.toString() + #tlds.toString()")
    90→    public SearchDomainsResponse searchDomains(List<String> keywords, List<String> tlds, int maxResults) {
    91→        log.debug("Searching domains with keywords: {} and tlds: {}", keywords, tlds);
    92→
    93→        List<String> domains = new ArrayList<>();
    94→        for (String keyword : keywords) {
    95→            for (String tld : tlds) {
    96→                String normalizedTld = tld.startsWith(".") ? tld : "." + tld;
    97→                domains.add(keyword.toLowerCase() + normalizedTld);
    98→            }
    99→        }
   100→
   101→        List<SearchDomainsResponse.DomainResultDto> results = new ArrayList<>();
   102→
   103→        for (String domain : domains.stream().limit(maxResults).toList()) {
   104→            CheckAvailabilityResponse check = checkAvailability(domain);
   105→            RegistrarResultDto registrar = check.getRegistrars().isEmpty() ? null : check.getRegistrars().get(0);
   106→
   107→            results.add(SearchDomainsResponse.DomainResultDto.builder()
   108→                .domain(domain)
   109→                .available(check.isAvailable())
   110→                .premium(registrar != null && registrar.isPremium())
   111→                .price(registrar != null && registrar.getPrice() != null
   112→                    ? registrar.getPrice().getRegistration()
   113→                    : null)
   114→                .registrar(registrar != null ? registrar.getName() : null)
   115→                .affiliateLink(registrar != null ? registrar.getAffiliateLink() : null)
   116→                .build());
   117→        }
   118→
   119→        return SearchDomainsResponse.builder()
   120→            .keywords(keywords)
   121→            .tlds(tlds)
   122→            .totalFound(results.size())
   123→            .results(results)
   124→            .suggestions(generateSuggestions(keywords))
   125→            .build();
   126→    }
