    private final DomainService domainService;
    private final CheckAvailabilityTool checkAvailabilityTool;
    private final SearchDomainsTool searchDomainsTool;
    private final SuggestAlternativesTool suggestAlternativesTool;

    public void registerTools(McpSyncServer server) {
        server.addTool(checkAvailabilityTool.getSpecification());
        server.addTool(searchDomainsTool.getSpecification());
        server.addTool(suggestAlternativesTool.getSpecification());
    }
}
