package com.lontsi.afservicelogic.domain.model;

import com.lontsi.afservicelogic.domain.event.DomainEvent;
import com.lontsi.afservicelogic.domain.event.ConversationStartedEvent;
import com.lontsi.afservicelogic.domain.event.MessageReceivedEvent;
import com.lontsi.afservicelogic.domain.event.ResponseGeneratedEvent;
import lombok.Getter;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.stream.Collectors;

/**
 * Conversation Aggregate Root
 * Represents a conversation session with an AI agent
 */
@Getter
public class Conversation {

    private final UUID id;
    private final ConversationId conversationId;
    private final String userId;

    private ConversationStatus status;
    private final Instant startedAt;
    private Instant endedAt;
    private Instant lastActivityAt;

    private final List<Message> messages;
    private int currentTurnNumber;

    // Domain events
    private final List<DomainEvent> domainEvents;

    // Conversation context for RAG
    private final ConversationContext context;

    public Conversation(String userId, String sessionId) {
        this.id = UUID.randomUUID();
        this.conversationId = ConversationId.fromSessionId(sessionId);
        this.userId = userId;
        this.status = ConversationStatus.ACTIVE;
        this.startedAt = Instant.now();
        this.lastActivityAt = Instant.now();
        this.messages = new ArrayList<>();
        this.currentTurnNumber = 0;
        this.domainEvents = new ArrayList<>();
        this.context = new ConversationContext();

        // Domain event
        this.domainEvents.add(new ConversationStartedEvent(
            UUID.randomUUID().toString(),
            conversationId.getValue(),
            userId,
            startedAt
        ));
    }

    // Constructor for reconstitution from DB
    public Conversation(
        UUID id,
        ConversationId conversationId,
        String userId,
        ConversationStatus status,
        Instant startedAt,
        Instant endedAt,
        Instant lastActivityAt,
        List<Message> messages,
        int currentTurnNumber,
        ConversationContext context
    ) {
        this.id = id;
        this.conversationId = conversationId;
        this.userId = userId;
        this.status = status;
        this.startedAt = startedAt;
        this.endedAt = endedAt;
        this.lastActivityAt = lastActivityAt;
        this.messages = messages != null ? new ArrayList<>(messages) : new ArrayList<>();
        this.currentTurnNumber = currentTurnNumber;
        this.domainEvents = new ArrayList<>();
        this.context = context != null ? context : new ConversationContext();
    }

    public void addUserMessage(String content, String transcriptionId) {
        currentTurnNumber++;

        Message message = new Message(
            conversationId,
            MessageRole.USER,
            content,
            currentTurnNumber,
            userId
        );

        messages.add(message);
        lastActivityAt = Instant.now();

        // Update context
        context.addUserInput(content);

        // Domain event
        domainEvents.add(new MessageReceivedEvent(
            UUID.randomUUID().toString(),
            conversationId.getValue(),
            message.getId().toString(),
            currentTurnNumber,
            content,
            transcriptionId,
            Instant.now()
        ));
    }

    public void addAssistantMessage(String content, String modelUsed, int tokenCount, long processingTimeMs) {
        Message message = new Message(
            conversationId,
            MessageRole.ASSISTANT,
            content,
            currentTurnNumber,
            "assistant"
        );

        // Set metadata
        message.getMetadata().setModelUsed(modelUsed);
        message.getMetadata().setTokenCount(tokenCount);
        message.getMetadata().setProcessingTimeMs(processingTimeMs);

        messages.add(message);
        lastActivityAt = Instant.now();

        // Update context
        context.addAssistantResponse(content);

        // Domain event
        domainEvents.add(new ResponseGeneratedEvent(
            UUID.randomUUID().toString(),
            conversationId.getValue(),
            message.getId().toString(),
            currentTurnNumber,
            content,
            modelUsed,
            tokenCount,
            Instant.now()
        ));
    }

    public void endConversation() {
        if (this.status == ConversationStatus.ACTIVE) {
            this.status = ConversationStatus.ENDED;
            this.endedAt = Instant.now();
        }
    }

    public List<Message> getRecentMessages(int count) {
        int size = messages.size();
        int fromIndex = Math.max(0, size - count);
        return new ArrayList<>(messages.subList(fromIndex, size));
    }

    public List<Message> getUserMessages() {
        return messages.stream()
            .filter(Message::isFromUser)
            .collect(Collectors.toList());
    }

    public List<Message> getAssistantMessages() {
        return messages.stream()
            .filter(Message::isFromAssistant)
            .collect(Collectors.toList());
    }

    public List<DomainEvent> pullDomainEvents() {
        List<DomainEvent> events = new ArrayList<>(this.domainEvents);
        this.domainEvents.clear();
        return events;
    }

    public int getMessageCount() {
        return messages.size();
    }
}
