package com.lontsi.afservicelogic.domain.service;

import com.lontsi.afservicelogic.domain.model.Conversation;
import com.lontsi.afservicelogic.domain.model.Message;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.stream.Collectors;

/**
 * Domain service for managing conversation history and context
 * Used for RAG - Retrieval Augmented Generation
 */
@Service
@Slf4j
public class ConversationHistoryService {

    private static final int MAX_CONTEXT_MESSAGES = 10;
    private static final int MAX_CONTEXT_CHARS = 4000;

    /**
     * Format conversation history for LLM context
     * Returns recent messages formatted for the LLM
     */
    public String formatConversationHistory(Conversation conversation) {
        List<Message> recentMessages = conversation.getRecentMessages(MAX_CONTEXT_MESSAGES);

        StringBuilder history = new StringBuilder();
        for (Message message : recentMessages) {
            String role = message.isFromUser() ? "User" : "Assistant";
            history.append(role)
                   .append(": ")
                   .append(message.getContent())
                   .append("\n\n");
        }

        String result = history.toString();

        // Truncate if too long
        if (result.length() > MAX_CONTEXT_CHARS) {
            result = result.substring(result.length() - MAX_CONTEXT_CHARS);
            // Find the first complete message
            int firstNewline = result.indexOf("\n\n");
            if (firstNewline > 0) {
                result = result.substring(firstNewline + 2);
            }
        }

        return result;
    }

    /**
     * Get conversation summary for RAG
     */
    public String getConversationSummary(Conversation conversation) {
        return String.format(
            "Conversation with %s started at %s. %d messages exchanged. Current topics: %s",
            conversation.getUserId(),
            conversation.getStartedAt(),
            conversation.getMessageCount(),
            String.join(", ", conversation.getContext().getTopics())
        );
    }

    /**
     * Extract key points from conversation for RAG embedding
     */
    public List<String> extractKeyPoints(Conversation conversation) {
        return conversation.getMessages().stream()
            .filter(Message::isFromUser)
            .map(Message::getContent)
            .collect(Collectors.toList());
    }
}
