package com.lontsi.afservicelogic.application.usecase;

import com.lontsi.afservicelogic.application.command.ProcessTranscriptionCommand;
import com.lontsi.afservicelogic.application.port.in.ConversationManagementPort;
import com.lontsi.afservicelogic.application.port.in.ConversationResult;
import com.lontsi.afservicelogic.application.port.out.*;
import com.lontsi.afservicelogic.domain.model.Conversation;
import com.lontsi.afservicelogic.domain.model.ConversationId;
import com.lontsi.afservicelogic.domain.repository.ConversationRepository;
import com.lontsi.afservicelogic.domain.service.ConversationHistoryService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Mono;

import java.time.Instant;
import java.util.List;
import java.util.UUID;

/**
 * Main use case for processing transcriptions and generating AI responses
 * This is the core business logic of the service
 */
@Service
@RequiredArgsConstructor
@Slf4j
public class ProcessTranscriptionUseCase {

    private final ConversationRepository conversationRepository;
    private final ConversationHistoryService historyService;
    private final LLMPort llmPort;
    private final EventPublisherPort eventPublisher;
    private final ConversationStoragePort storagePort;

    public Mono<ConversationResult> execute(ProcessTranscriptionCommand command) {
        log.info("Processing transcription for session: {}, turn: {}", 
            command.getSessionId(), command.getTurnNumber());

        long startTime = System.currentTimeMillis();
        ConversationId conversationId = ConversationId.fromSessionId(command.getSessionId());

        return conversationRepository.findByIdOrCreate(conversationId, command.getUserId())
            // 1. Add user message to conversation
            .doOnNext(conversation -> {
                conversation.addUserMessage(
                    command.getTranscriptionText(), 
                    command.getTranscriptionId()
                );
                log.info("User message added to conversation {}", conversationId.getValue());
            })

            // 2. Retrieve relevant context from RAG
            .flatMap(conversation -> 
                storagePort.getRelevantContext(command.getUserId(), command.getTranscriptionText())
                    .defaultIfEmpty(List.of())
                    .map(context -> new ConversationWithContext(conversation, context))
            )

            // 3. Format conversation history
            .map(cwc -> {
                String history = historyService.formatConversationHistory(cwc.conversation);
                return new ConversationWithHistory(cwc.conversation, history, cwc.context);
            })

            // 4. Generate LLM response
            .flatMap(cwh -> {
                log.info("Calling LLM for session: {}", command.getSessionId());
                return llmPort.generateResponseWithContext(
                    command.getTranscriptionText(),
                    cwh.history,
                    cwh.context
                ).map(response -> new ConversationWithResponse(cwh.conversation, response));
            })

            // 5. Add assistant message to conversation
            .doOnNext(cwr -> {
                LLMResponse response = cwr.response;
                cwr.conversation.addAssistantMessage(
                    response.getContent(),
                    response.getModelUsed(),
                    response.getTokenCount(),
                    response.getProcessingTimeMs()
                );
                log.info("Assistant response added to conversation {}", conversationId.getValue());
            })

            // 6. Save conversation
            .flatMap(cwr -> conversationRepository.save(cwr.conversation)
                .map(saved -> new ConversationWithResponse(saved, cwr.response))
            )

            // 7. Store conversation embedding for RAG
            .flatMap(cwr -> 
                storagePort.storeConversationEmbedding(
                    command.getSessionId(),
                    command.getUserId(),
                    command.getTranscriptionText() + " " + cwr.response.getContent()
                ).thenReturn(cwr)
            )

            // 8. Publish AgentResponse event to Pulsar
            .flatMap(cwr -> {
                AgentResponseEvent event = new AgentResponseEvent(
                    UUID.randomUUID().toString(),
                    command.getSessionId(),
                    command.getTurnNumber(),
                    cwr.response.getContent(),
                    cwr.conversation.getContext().getCurrentIntent(),
                    cwr.response.getModelUsed(),
                    Instant.now()
                );

                return eventPublisher.publishAgentResponse(event)
                    .thenReturn(cwr);
            })

            // 9. Publish domain events
            .flatMap(cwr -> {
                return Mono.when(
                    cwr.conversation.pullDomainEvents().stream()
                        .map(eventPublisher::publish)
                        .toArray(Mono[]::new)
                ).thenReturn(cwr);
            })

            // 10. Build result
            .map(cwr -> {
                long processingTime = System.currentTimeMillis() - startTime;
                log.info("Transcription processed successfully for session: {} in {}ms", 
                    command.getSessionId(), processingTime);

                return new ConversationResult(
                    command.getSessionId(),
                    command.getTurnNumber(),
                    command.getTranscriptionText(),
                    cwr.response.getContent(),
                    cwr.response.getModelUsed(),
                    processingTime
                );
            })

            .doOnError(error -> log.error("Error processing transcription for session: {}", 
                command.getSessionId(), error));
    }

    // Helper classes for reactive chain
    private record ConversationWithContext(Conversation conversation, List<String> context) {}
    private record ConversationWithHistory(Conversation conversation, String history, List<String> context) {}
    private record ConversationWithResponse(Conversation conversation, LLMResponse response) {}
}
