package com.lontsi.afservicelogic.application.usecase;

import com.lontsi.afservicelogic.application.port.in.ConversationHistoryResult;
import com.lontsi.afservicelogic.application.query.GetConversationHistoryQuery;
import com.lontsi.afservicelogic.domain.model.Conversation;
import com.lontsi.afservicelogic.domain.model.ConversationId;
import com.lontsi.afservicelogic.domain.model.Message;
import com.lontsi.afservicelogic.domain.repository.ConversationRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Mono;

import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
public class GetConversationHistoryUseCase {

    private final ConversationRepository conversationRepository;

    public Mono<ConversationHistoryResult> execute(GetConversationHistoryQuery query) {
        log.info("Retrieving conversation history for session: {}", query.getSessionId());

        ConversationId conversationId = ConversationId.fromSessionId(query.getSessionId());

        return conversationRepository.findById(conversationId)
            .map(conversation -> buildHistoryResult(conversation, query.getLimit()))
            .doOnSuccess(result -> log.info("Retrieved {} messages for session: {}", 
                result.getMessageCount(), query.getSessionId()))
            .doOnError(error -> log.error("Error retrieving conversation history for session: {}", 
                query.getSessionId(), error));
    }

    private ConversationHistoryResult buildHistoryResult(Conversation conversation, Integer limit) {
        List<Message> messages = limit != null && limit > 0
            ? conversation.getRecentMessages(limit)
            : conversation.getMessages();

        List<ConversationHistoryResult.MessageDto> messageDtos = messages.stream()
            .map(msg -> new ConversationHistoryResult.MessageDto(
                msg.getRole().name(),
                msg.getContent(),
                msg.getTurnNumber(),
                msg.getCreatedAt()
            ))
            .collect(Collectors.toList());

        return new ConversationHistoryResult(
            conversation.getConversationId().getValue(),
            conversation.getUserId(),
            conversation.getStartedAt(),
            messages.size(),
            messageDtos
        );
    }
}
