package com.lontsi.afservicelogic.infrastructure.persistence;

import com.lontsi.afservicelogic.domain.model.*;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.mapping.Document;

import java.time.Instant;
import java.util.List;
import java.util.UUID;
import java.util.stream.Collectors;

@Document(collection = "conversations")
@Data
@NoArgsConstructor
@AllArgsConstructor
public class ConversationDocument {

    @Id
    private String id;
    private String conversationId;
    private String userId;
    private String status;
    private Instant startedAt;
    private Instant endedAt;
    private Instant lastActivityAt;
    private List<MessageDocument> messages;
    private int currentTurnNumber;
    private ConversationContextDocument context;

    @Data
    @NoArgsConstructor
    @AllArgsConstructor
    public static class MessageDocument {
        private String id;
        private String role;
        private String content;
        private int turnNumber;
        private String userId;
        private Instant createdAt;
        private MessageMetadataDocument metadata;
    }

    @Data
    @NoArgsConstructor
    @AllArgsConstructor
    public static class MessageMetadataDocument {
        private String modelUsed;
        private Integer tokenCount;
        private Double confidence;
        private Long processingTimeMs;
    }

    @Data
    @NoArgsConstructor
    @AllArgsConstructor
    public static class ConversationContextDocument {
        private List<String> topics;
        private List<String> intents;
        private String currentIntent;
