package com.lontsi.afservicelogic.infrastructure.persistence;

import com.lontsi.afservicelogic.domain.model.Conversation;
import com.lontsi.afservicelogic.domain.model.ConversationId;
import com.lontsi.afservicelogic.domain.repository.ConversationRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

import java.time.Instant;

/**
 * MongoDB adapter for ConversationRepository
 * Implements the domain repository interface
 */
@Component
@RequiredArgsConstructor
@Slf4j
public class ConversationRepositoryAdapter implements ConversationRepository {

    private final ReactiveConversationMongoRepository mongoRepository;

    @Override
    public Mono<Conversation> save(Conversation conversation) {
        log.debug("Saving conversation: {}", conversation.getConversationId().getValue());

        ConversationDocument document = ConversationDocument.fromConversation(conversation);

        return mongoRepository.save(document)
            .map(ConversationDocument::toDomain)
            .doOnSuccess(saved -> log.debug("Conversation saved: {}", 
                saved.getConversationId().getValue()));
    }

    @Override
    public Mono<Conversation> findById(ConversationId conversationId) {
        log.debug("Finding conversation: {}", conversationId.getValue());

        return mongoRepository.findByConversationId(conversationId.getValue())
            .map(ConversationDocument::toDomain);
    }

    @Override
    public Mono<Conversation> findByIdOrCreate(ConversationId conversationId, String userId) {
        return findById(conversationId)
            .switchIfEmpty(Mono.defer(() -> {
                log.info("Creating new conversation for session: {}", conversationId.getValue());
                Conversation newConversation = new Conversation(userId, conversationId.getValue());
                return save(newConversation);
            }));
    }

    @Override
    public Flux<Conversation> findByUserId(String userId) {
        return mongoRepository.findByUserId(userId)
            .map(ConversationDocument::toDomain);
    }

    @Override
    public Flux<Conversation> findActiveByUserId(String userId) {
        return mongoRepository.findByUserIdAndStatus(userId, "ACTIVE")
            .map(ConversationDocument::toDomain);
    }

    @Override
    public Flux<Conversation> findByUserIdAndDateRange(String userId, Instant from, Instant to) {
        return mongoRepository.findByUserIdAndStartedAtBetween(userId, from, to)
            .map(ConversationDocument::toDomain);
    }

    @Override
    public Mono<Boolean> existsById(ConversationId conversationId) {
        return mongoRepository.existsByConversationId(conversationId.getValue());
    }

    @Override
    public Mono<Void> deleteById(ConversationId conversationId) {
        return mongoRepository.findByConversationId(conversationId.getValue())
            .flatMap(mongoRepository::delete);
    }
}
