package com.lontsi.afservicelogic.infrastructure.ai;

import com.lontsi.afservicelogic.application.port.out.LLMPort;
import com.lontsi.afservicelogic.application.port.out.LLMResponse;
import dev.langchain4j.model.chat.ChatLanguageModel;
import dev.langchain4j.data.message.AiMessage;
import dev.langchain4j.data.message.SystemMessage;
import dev.langchain4j.data.message.UserMessage;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import reactor.core.publisher.Mono;
import reactor.core.scheduler.Schedulers;

import java.util.ArrayList;
import java.util.List;

/**
 * LangChain4j adapter for LLM integration
 * Implements the LLMPort interface using LangChain4j with OpenAI (GitHub Copilot / GPT-4)
 */
@Component
@RequiredArgsConstructor
@Slf4j
public class LangChain4jAdapter implements LLMPort {

    private final ChatLanguageModel chatModel;

    private static final String SYSTEM_PROMPT = """
        Tu es Sara, un assistant bancaire intelligent pour Afriland First Bank.
        Tu es amicale, professionnelle et tu aides les clients avec leurs besoins bancaires.

        Tes responsabilités:
        - Répondre aux questions sur les comptes et transactions
        - Aider avec les opérations bancaires simples
        - Fournir des informations sur les produits et services de la banque
        - Escalader vers un conseiller humain si nécessaire

        Tu dois toujours:
        - Être polie et professionnelle
        - Parler en français (ou en anglais si le client préfère)
        - Demander confirmation avant toute opération sensible
        - Protéger les informations confidentielles du client
        """;

    @Override
    public Mono<LLMResponse> generateResponse(String userMessage, String conversationHistory) {
        return generateResponseWithContext(userMessage, conversationHistory, List.of());
    }

    @Override
    public Mono<LLMResponse> generateResponseWithContext(
        String userMessage, 
        String conversationHistory,
        List<String> retrievedContext
    ) {
        log.info("Generating LLM response for user message: {}", 
            userMessage.substring(0, Math.min(50, userMessage.length())));

        return Mono.fromCallable(() -> {
            long startTime = System.currentTimeMillis();

            // Build messages list
            List<dev.langchain4j.data.message.ChatMessage> messages = new ArrayList<>();

            // System message
            messages.add(SystemMessage.from(SYSTEM_PROMPT));

            // Add context if available
            if (retrievedContext != null && !retrievedContext.isEmpty()) {
                String contextMessage = "Contexte des conversations précédentes:\n" + 
                    String.join("\n", retrievedContext);
                messages.add(SystemMessage.from(contextMessage));
            }

            // Add conversation history
            if (conversationHistory != null && !conversationHistory.isEmpty()) {
                messages.add(SystemMessage.from("Historique de la conversation:\n" + conversationHistory));
            }

            // Current user message
            messages.add(UserMessage.from(userMessage));

            // Call LLM
            log.debug("Calling chat model with {} messages", messages.size());
            dev.langchain4j.model.output.Response<AiMessage> response = chatModel.generate(messages);

            long processingTime = System.currentTimeMillis() - startTime;

            String content = response.content().text();
            int tokenCount = estimateTokenCount(content);

            log.info("LLM response generated in {}ms, ~{} tokens", processingTime, tokenCount);

            return new LLMResponse(
                content,
                "gpt-4",
                tokenCount,
                processingTime,
                0.95
            );
        })
        .subscribeOn(Schedulers.boundedElastic())
        .doOnError(error -> log.error("Error generating LLM response", error));
    }

    private int estimateTokenCount(String text) {
        // Rough estimation: ~4 characters per token
        return text.length() / 4;
    }
}
