/**
 * Pulsar adapter for publishing events
 */
@Component
@RequiredArgsConstructor
@Slf4j
public class PulsarEventPublisher implements EventPublisherPort {

    private final PulsarTemplate<Object> pulsarTemplate;

    private static final String AGENT_RESPONSE_TOPIC = "persistent://afriland/audio/agent-responses";
    private static final String DOMAIN_EVENTS_TOPIC = "persistent://afriland/logic/domain-events";

    @Override
    public Mono<Void> publish(DomainEvent event) {
        log.debug("Publishing domain event: {}", event.getEventType());

        return Mono.fromRunnable(() -> {
            try {
                pulsarTemplate.send(DOMAIN_EVENTS_TOPIC, event);
                log.debug("Domain event published: {}", event.getEventType());
            } catch (Exception e) {
                log.error("Failed to publish domain event", e);
                throw new RuntimeException("Failed to publish event", e);
            }
        });
    }

    @Override
    public Mono<Void> publishAgentResponse(AgentResponseEvent event) {
        log.info("Publishing agent response for session: {}, turn: {}", 
            event.getSessionId(), event.getTurnNumber());

        return Mono.fromRunnable(() -> {
            try {
                pulsarTemplate.send(AGENT_RESPONSE_TOPIC, event);
                log.info("Agent response published successfully for session: {}", event.getSessionId());
            } catch (Exception e) {
                log.error("Failed to publish agent response", e);
                throw new RuntimeException("Failed to publish agent response", e);
            }
        });
    }
