import com.lontsi.afservicelogic.application.handler.TranscriptionReceivedHandler;
import com.lontsi.afservicelogic.application.handler.TranscriptionReceivedHandler.TranscriptionReceivedEvent;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.apache.pulsar.client.api.Message;
import org.springframework.pulsar.annotation.PulsarListener;
import org.springframework.stereotype.Component;

/**
 * Pulsar consumer for transcription events
 * Listens to transcriptions from audio-ingestor service
 */
@Component
@RequiredArgsConstructor
@Slf4j
public class PulsarTranscriptionConsumer {

    private final TranscriptionReceivedHandler handler;

    @PulsarListener(
        subscriptionName = "logic-transcription-sub",
        topics = "persistent://afriland/audio/transcriptions",
        schemaType = org.springframework.pulsar.annotation.PulsarListener.SchemaType.JSON
    )
    public void listenTranscription(Message<TranscriptionReceivedEventDto> message) {
        TranscriptionReceivedEventDto dto = message.getValue();

        log.info("Received transcription event for session: {}, turn: {}", 
            dto.sessionId(), dto.turnNumber());

        TranscriptionReceivedEvent event = new TranscriptionReceivedEvent(
            dto.eventId(),
            dto.sessionId(),
            dto.userId(),
            dto.transcriptionId(),
            dto.turnNumber(),
            dto.text(),
            dto.isFinal(),
            dto.confidence(),
            dto.sttProvider()
        );

        handler.handle(event)
            .doOnSuccess(v -> log.info("Transcription processed successfully for session: {}", 
                dto.sessionId()))
            .doOnError(error -> log.error("Failed to process transcription for session: {}", 
                dto.sessionId(), error))
            .subscribe();
    }

    /**
     * DTO matching the event from audio-ingestor service
     */
    public record TranscriptionReceivedEventDto(
        String eventId,
        String sessionId,
        String userId,
        String transcriptionId,
        int turnNumber,
        String text,
        boolean isFinal,
        double confidence,
        String sttProvider
    ) {}
}
