        String userMessage = "What is the weather?";
        conversation.addUserMessage(userMessage, "trans-123");

        String assistantMessage = "The weather is sunny today.";
        String modelUsed = "gpt-4";
        int tokenCount = 50;
        long processingTime = 1500L;

        conversation.addAssistantMessage(assistantMessage, modelUsed, tokenCount, processingTime);

        assertThat(conversation.getMessages()).hasSize(2);
