    15→/**
    16→ * MCP Server Runner for CDomain.
    17→ *
    18→ * <p>Starts the MCP server with stdio transport when the 'mcp' profile is active.
    19→ * This allows AI agents like Claude to interact with the domain service.
    20→ *
    21→ * <p>Available tools:
    22→ * <ul>
    23→ *   <li>check-availability: Check if a domain is available</li>
    24→ *   <li>search-domains: Search for available domains</li>
    25→ *   <li>suggest-alternatives: Get domain suggestions</li>
    26→ * </ul>
    27→ */
    28→@Slf4j
    29→@Component
    30→@Profile("mcp")
    31→@RequiredArgsConstructor
    32→public class McpServerRunner implements CommandLineRunner {
    33→
    34→    private static final String SERVER_NAME = "cdomain-mcp";
    35→    private static final String SERVER_VERSION = "1.0.0";
    36→
    37→    private final CheckAvailabilityTool checkAvailabilityTool;
    38→    private final SearchDomainsTool searchDomainsTool;
    39→    private final SuggestAlternativesTool suggestAlternativesTool;
    40→
    41→    @Override
    42→    public void run(String... args) throws Exception {
    43→        // Create stdio transport provider
    44→        StdioServerTransportProvider transportProvider = new StdioServerTransportProvider();
    45→
    46→        // Build and configure the MCP server
    47→        McpSyncServer server = McpServer.sync(transportProvider)
    48→            .serverInfo(SERVER_NAME, SERVER_VERSION)
    49→            .tool(
    50→                checkAvailabilityTool.getToolDefinition(),
    51→                (exchange, arguments) -> checkAvailabilityTool.handle(arguments)
    52→            )
    53→            .tool(
    54→                searchDomainsTool.getToolDefinition(),
    55→                (exchange, arguments) -> searchDomainsTool.handle(arguments)
    56→            )
    57→            .tool(
    58→                suggestAlternativesTool.getToolDefinition(),
    59→                (exchange, arguments) -> suggestAlternativesTool.handle(arguments)
    60→            )
    61→            .build();
    62→
    63→        // Keep the server running until interrupted
    64→        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
    65→            server.closeGracefully();
    66→        }));
    67→
    68→        // Block the main thread
    69→        Thread.currentThread().join();
    70→    }
    71→}
