     1→package com.cdomain.service;
     2→
     3→import com.cdomain.dto.response.RateLimitInfo;
     4→import com.cdomain.exception.RateLimitExceededException;
     5→import com.cdomain.model.enums.UserTier;
     6→import lombok.RequiredArgsConstructor;
     7→import lombok.extern.slf4j.Slf4j;
     8→import org.springframework.data.redis.core.StringRedisTemplate;
     9→import org.springframework.stereotype.Service;
    10→
    11→import java.time.Duration;
    12→import java.time.Instant;
    13→import java.time.LocalDate;
    14→import java.time.ZoneOffset;
    15→
    16→/**
    17→ * Service for API rate limiting using Redis.
    18→ *
    19→ * <p>Implements a sliding window rate limiter with different strategies
    20→ * for anonymous and authenticated users:
    21→ * <ul>
    22→ *   <li><b>Anonymous:</b> Per-minute IP-based limit (30 requests/minute)</li>
    23→ *   <li><b>Authenticated:</b> Daily limit based on user tier</li>
    24→ * </ul>
    25→ *
    26→ * <p><b>Tier Limits:</b>
    27→ * <ul>
    28→ *   <li>FREE: 100 requests/day</li>
    29→ *   <li>PRO: 1,000 requests/day</li>
    30→ *   <li>ENTERPRISE: 10,000 requests/day</li>
    31→ * </ul>
    32→ *
    33→ * <p><b>Redis Keys:</b>
    34→ * <ul>
    35→ *   <li>{@code ratelimit:minute:{ip}} - Anonymous per-minute counter</li>
    36→ *   <li>{@code ratelimit:daily:{userId}:{date}} - User daily counter</li>
    37→ * </ul>
    38→ *
    39→ * @author CDomain Team
    40→ * @version 1.0.0
    41→ * @see RateLimitExceededException
    42→ */
    43→@Slf4j
    44→@Service
    45→@RequiredArgsConstructor
    46→public class RateLimitService {
    47→
    48→    private final StringRedisTemplate redisTemplate;
    49→
    50→    private static final String MINUTE_KEY_PREFIX = "ratelimit:minute:";
    51→    private static final String DAILY_KEY_PREFIX = "ratelimit:daily:";
    52→
    53→    private static final int ANONYMOUS_PER_MINUTE = 30;
    54→
    55→    /**
    56→     * Check rate limit for anonymous users (IP-based)
    57→     */
    58→    public RateLimitInfo checkAnonymousRateLimit(String ipAddress) {
    59→        String key = MINUTE_KEY_PREFIX + ipAddress;
    60→
    61→        Long count = redisTemplate.opsForValue().increment(key);
    62→        if (count == 1) {
    63→            redisTemplate.expire(key, Duration.ofMinutes(1));
    64→        }
    65→
    66→        int remaining = Math.max(0, ANONYMOUS_PER_MINUTE - count.intValue());
    67→        long resetAt = Instant.now().plusSeconds(60).toEpochMilli();
    68→
    69→        if (count > ANONYMOUS_PER_MINUTE) {
    70→            throw new RateLimitExceededException(
    71→                "Rate limit exceeded. Please wait before making more requests.",
    72→                ANONYMOUS_PER_MINUTE,
    73→                resetAt
    74→            );
    75→        }
    76→
    77→        return RateLimitInfo.builder()
    78→            .limit(ANONYMOUS_PER_MINUTE)
    79→            .remaining(remaining)
    80→            .resetAt(resetAt)
    81→            .build();
    82→    }
    83→
    84→    /**
    85→     * Check rate limit for authenticated users (daily limit based on tier)
    86→     */
    87→    public RateLimitInfo checkUserRateLimit(String userId, UserTier tier) {
    88→        String today = LocalDate.now().toString();
    89→        String key = DAILY_KEY_PREFIX + userId + ":" + today;
    90→
    91→        Long count = redisTemplate.opsForValue().increment(key);
    92→        if (count == 1) {
    93→            // Set expiry at end of day
    94→            long secondsUntilMidnight = LocalDate.now().plusDays(1)
    95→                .atStartOfDay(ZoneOffset.UTC)
    96→                .toEpochSecond() - Instant.now().getEpochSecond();
    97→            redisTemplate.expire(key, Duration.ofSeconds(secondsUntilMidnight));
    98→        }
    99→
   100→        int limit = tier.getDailyLimit();
   101→        int remaining = Math.max(0, limit - count.intValue());
   102→        long resetAt = LocalDate.now().plusDays(1)
   103→            .atStartOfDay(ZoneOffset.UTC)
   104→            .toInstant()
   105→            .toEpochMilli();
   106→
   107→        if (count > limit) {
   108→            throw new RateLimitExceededException(
   109→                "Daily request limit exceeded. Upgrade your plan for more requests.",
   110→                limit,
   111→                resetAt
   112→            );
   113→        }
   114→
   115→        return RateLimitInfo.builder()
   116→            .limit(limit)
   117→            .remaining(remaining)
   118→            .resetAt(resetAt)
   119→            .build();
   120→    }
   121→
   122→    /**
   123→     * Get current rate limit status without incrementing
   124→     */
   125→    public RateLimitInfo getRateLimitStatus(String userId, UserTier tier) {
   126→        String today = LocalDate.now().toString();
   127→        String key = DAILY_KEY_PREFIX + userId + ":" + today;
   128→
   129→        String countStr = redisTemplate.opsForValue().get(key);
   130→        int count = countStr != null ? Integer.parseInt(countStr) : 0;
   131→
   132→        int limit = tier.getDailyLimit();
   133→        int remaining = Math.max(0, limit - count);
   134→        long resetAt = LocalDate.now().plusDays(1)
   135→            .atStartOfDay(ZoneOffset.UTC)
   136→            .toInstant()
   137→            .toEpochMilli();
   138→
   139→        return RateLimitInfo.builder()
   140→            .limit(limit)
   141→            .remaining(remaining)
   142→            .resetAt(resetAt)
   143→            .build();
   144→    }
   145→}
