    15→ *
    16→ * <p>Provides common functionality for HTTP-based registrar integrations:
    17→ * <ul>
    18→ *   <li>WebClient setup with base URL configuration</li>
    19→ *   <li>Timeout handling (10 seconds default)</li>
    20→ *   <li>Bulk availability check implementation</li>
    21→ *   <li>Error handling with {@link RegistrarException}</li>
    22→ *   <li>TLD extraction utility</li>
    23→ * </ul>
    24→ *
    25→ * <p><b>Usage:</b> Extend this class and implement:
    26→ * <ul>
    27→ *   <li>{@link #getName()} - Registrar display name</li>
    28→ *   <li>{@link #getSlug()} - Registrar identifier</li>
    29→ *   <li>{@link #isAvailable()} - Configuration check</li>
    30→ *   <li>{@link #checkAvailability(String)} - Domain availability check</li>
    31→ *   <li>{@link #getPricing(String)} - Domain pricing</li>
    32→ *   <li>{@link #getAffiliateLink(String)} - Purchase link generation</li>
    33→ * </ul>
    34→ *
    35→ * @author CDomain Team
    36→ * @version 1.0.0
    37→ * @see RegistrarAdapter
    38→ */
    39→@Slf4j
    40→public abstract class AbstractRegistrarAdapter implements RegistrarAdapter {
    41→
    42→    protected final WebClient webClient;
    43→    protected static final Duration TIMEOUT = Duration.ofSeconds(10);
    44→
    45→    /**
    46→     * Constructs adapter with configured WebClient.
    47→     *
    48→     * @param webClientBuilder Spring WebClient builder
    49→     * @param baseUrl base URL for registrar API
    50→     */
    51→    protected AbstractRegistrarAdapter(WebClient.Builder webClientBuilder, String baseUrl) {
    52→        this.webClient = webClientBuilder.baseUrl(baseUrl).build();
    53→    }
    54→
    55→    /**
    56→     * {@inheritDoc}
    57→     * <p>Default implementation checks each domain sequentially.
    58→     * Override for registrars with native bulk API support.
    59→     */
    60→    @Override
    61→    public List<DomainAvailability> checkBulkAvailability(List<String> domains) {
    62→        return domains.stream()
    63→            .map(domain -> {
    64→                try {
    65→                    return checkAvailability(domain);
    66→                } catch (Exception e) {
    67→                    log.warn("Failed to check availability for {}: {}", domain, e.getMessage());
    68→                    return DomainAvailability.builder()
    69→                        .domain(domain)
    70→                        .available(false)
    71→                        .build();
    72→                }
    73→            })
    74→            .collect(Collectors.toList());
    75→    }
    76→
    77→    /**
    78→     * Executes a WebClient request with timeout and error handling.
    79→     *
    80→     * @param <T> response type
    81→     * @param request the Mono request to execute
    82→     * @param operation operation name for logging
    83→     * @return the response body
    84→     * @throws RegistrarException on API errors or timeout
    85→     */
    86→    protected <T> T executeRequest(Mono<T> request, String operation) {
    87→        try {
    88→            return request.block(TIMEOUT);
    89→        } catch (WebClientResponseException e) {
    90→            log.error("{} {} API error: {} - {}", getName(), operation, e.getStatusCode(), e.getMessage());
    91→            throw RegistrarException.apiError(getName(), e.getMessage());
    92→        } catch (Exception e) {
    93→            log.error("{} {} failed: {}", getName(), operation, e.getMessage());
    94→            throw RegistrarException.unavailable(getName());
    95→        }
    96→    }
