     9→import org.springframework.web.reactive.function.client.WebClient;
    10→import reactor.core.publisher.Mono;
    11→
    12→@Component
    13→public class FasterWhisperAdapter implements TranscriptionPort {
    14→
    15→    private final WebClient sttWebClient;
    16→
    17→    public FasterWhisperAdapter(WebClient sttWebClient) {
    18→        this.sttWebClient = sttWebClient;
    19→    }
    20→
    21→    @Override
    22→    public Mono<TranscriptionResult> transcribe(byte[] audioData, String language) {
    23→        MultipartBodyBuilder builder = new MultipartBodyBuilder();
    24→        builder.part("file", new ByteArrayResource(audioData) {
    25→            @Override
    26→            public String getFilename() {
    27→                return "audio.wav";
    28→            }
    29→        }).contentType(MediaType.APPLICATION_OCTET_STREAM);
    30→
    31→        return sttWebClient.post()
    32→                .uri(uriBuilder -> uriBuilder.path("/transcribe")
    33→                        .queryParam("language", language)
    34→                        .build())
    35→                .contentType(MediaType.MULTIPART_FORM_DATA)
    36→                .body(BodyInserters.fromMultipartData(builder.build()))
    37→                .retrieve()
    38→                .bodyToMono(SttResponse.class)
    39→                .map(r -> new TranscriptionResult(r.text(), r.language(), r.languageProbability(), r.duration()));
    40→    }
    41→
    42→    private record SttResponse(String text, String language, double languageProbability, double duration) {}
    43→}
