     2→
     3→import com.lontsi.afserviceaudioingestor.application.command.ProcessAudioChunkCommand;
     4→import com.lontsi.afserviceaudioingestor.application.port.in.AudioChunkResult;
     5→import com.lontsi.afserviceaudioingestor.application.port.out.AudioStoragePort;
     6→import com.lontsi.afserviceaudioingestor.application.port.out.EventPublisherPort;
     7→import com.lontsi.afserviceaudioingestor.application.port.out.SessionCachePort;
     8→import com.lontsi.afserviceaudioingestor.application.port.out.TranscriptionPort;
     9→import com.lontsi.afserviceaudioingestor.domain.event.AudioChunkReceivedEvent;
    10→import com.lontsi.afserviceaudioingestor.domain.event.SilenceDetectedEvent;
    11→import com.lontsi.afserviceaudioingestor.domain.model.AudioChunk;
    12→import com.lontsi.afserviceaudioingestor.domain.model.AudioData;
    13→import com.lontsi.afserviceaudioingestor.domain.model.Transcription;
    14→import com.lontsi.afserviceaudioingestor.domain.repository.AudioChunkRepository;
    15→import com.lontsi.afserviceaudioingestor.domain.repository.TranscriptionRepository;
    16→import com.lontsi.afserviceaudioingestor.domain.service.AudioProcessingService;
    17→import com.lontsi.afserviceaudioingestor.domain.service.VoiceActivityDetector;
    18→import org.springframework.stereotype.Service;
    19→import reactor.core.publisher.Mono;
    20→import reactor.core.scheduler.Schedulers;
    21→
    22→import java.time.Instant;
    23→import java.util.UUID;
    24→
    25→@Service
    26→public class ProcessAudioChunkUseCase {
    27→
    28→    private final AudioChunkRepository chunkRepository;
    29→    private final TranscriptionRepository transcriptionRepository;
    30→    private final AudioStoragePort audioStorage;
    31→    private final SessionCachePort sessionCache;
    32→    private final EventPublisherPort eventPublisher;
    33→    private final TranscriptionPort stt;
    34→    private final AudioProcessingService audioProcessing;
    35→    private final VoiceActivityDetector vad;
    36→
    37→    public ProcessAudioChunkUseCase(AudioChunkRepository chunkRepository,
    38→                                    TranscriptionRepository transcriptionRepository,
    39→                                    AudioStoragePort audioStorage,
    40→                                    SessionCachePort sessionCache,
    41→                                    EventPublisherPort eventPublisher,
    42→                                    TranscriptionPort stt,
    43→                                    AudioProcessingService audioProcessing,
    44→                                    VoiceActivityDetector vad) {
    45→        this.chunkRepository = chunkRepository;
    46→        this.transcriptionRepository = transcriptionRepository;
    47→        this.audioStorage = audioStorage;
    48→        this.sessionCache = sessionCache;
    49→        this.eventPublisher = eventPublisher;
    50→        this.stt = stt;
    51→        this.audioProcessing = audioProcessing;
    52→        this.vad = vad;
    53→    }
    54→
    55→    public Mono<AudioChunkResult> execute(ProcessAudioChunkCommand command) {
    56→        AudioData audioData = audioProcessing.validate(command.audioData(), command.filename());
    57→
    58→        return sessionCache.getCurrentTurn(command.sessionId())
    59→                .defaultIfEmpty(command.sequenceNumber())
    60→                .flatMap(turnNumber -> {
    61→                    AudioChunk chunk = AudioChunk.inbound(command.sessionId(), turnNumber,
    62→                            audioProcessing.buildStorageKey(command.sessionId(), turnNumber, chunk(command)));
    63→
    64→                    return audioStorage.store(chunk.getStorageKey(), command.audioData())
    65→                            .then(Mono.fromCallable(() -> chunkRepository.save(chunk)).subscribeOn(Schedulers.boundedElastic()))
    66→                            .then(analyzeAndPublish(command.sessionId(), turnNumber, chunk.getStorageKey(), audioData))
    67→                            .map(vadResult -> new AudioChunkResult(chunk.getId(), vadResult.speechDetected(), vadResult.turnEnded()));
    68→                });
    69→    }
    70→
    71→    private Mono<VoiceActivityDetector.VadResult> analyzeAndPublish(
    72→            String sessionId, int turnNumber, String storageKey, AudioData audioData) {
    73→        return sessionCache.getVadState(sessionId)
    74→                .defaultIfEmpty(VoiceActivityDetector.VadState.initial())
    75→                .flatMap(vadState -> {
    76→                    VoiceActivityDetector.VadResult result = vad.analyze(audioData, vadState);
    77→                    var newState = new VoiceActivityDetector.VadState(
    78→                            result.totalSpeechDurationMs(), result.consecutiveSilenceMs());
    79→
    80→                    Mono<Void> saveState = sessionCache.saveVadState(sessionId, newState);
    81→                    Mono<Void> publishChunk = eventPublisher.publishAudioChunk(
    82→                            new AudioChunkReceivedEvent(sessionId, turnNumber, storageKey, Instant.now()));
    83→
    84→                    Mono<Void> publishSilence = result.turnEnded()
    85→                            ? eventPublisher.publishSilenceDetected(
    86→                                    new SilenceDetectedEvent(sessionId, turnNumber, result.consecutiveSilenceMs(), Instant.now()))
    87→                              .then(transcribeAndPersist(sessionId, turnNumber, storageKey))
    88→                            : Mono.empty();
    89→
    90→                    return saveState.then(publishChunk).then(publishSilence).thenReturn(result);
    91→                });
    92→    }
    93→
    94→    private String chunk(ProcessAudioChunkCommand command) {
    95→        return java.util.UUID.randomUUID().toString().substring(0, 8);
    96→    }
    97→
    98→    /**
    99→     * Récupère l'audio depuis MinIO, transcrit via faster-whisper, persiste le résultat.
   100→     */
   101→    private Mono<Void> transcribeAndPersist(String sessionId, int turnNumber, String storageKey) {
   102→        return audioStorage.retrieve(storageKey)
   103→                .flatMap(audio -> stt.transcribe(audio, "fr"))
   104→                .flatMap(result -> {
   105→                    Transcription transcription = new Transcription(
   106→                            UUID.randomUUID(), sessionId, turnNumber,
   107→                            result.text(), true, result.languageProbability());
   108→                    return Mono.fromCallable(() -> transcriptionRepository.save(transcription))
   109→                            .subscribeOn(Schedulers.boundedElastic());
   110→                })
   111→                .then();
   112→    }
   113→}
