    20→    public VadResult analyze(AudioData audioData, VadState currentState) {
    21→        double rms = computeRms(audioData.rawData());
    22→        boolean speechDetected = rms > SPEECH_THRESHOLD_RMS;
    23→
    24→        long consecutiveSilenceMs;
    25→        long totalSpeechDurationMs = currentState.totalSpeechDurationMs();
    26→
    27→        if (speechDetected) {
    28→            consecutiveSilenceMs = 0;
    29→            totalSpeechDurationMs += audioData.durationMs();
    30→        } else {
    31→            consecutiveSilenceMs = currentState.consecutiveSilenceMs() + audioData.durationMs();
    32→        }
    33→
    34→        boolean turnEnded = consecutiveSilenceMs >= SILENCE_THRESHOLD_MS && totalSpeechDurationMs > 0;
    35→
    36→        return new VadResult(speechDetected, turnEnded, consecutiveSilenceMs, totalSpeechDurationMs);
    37→    }
