    39→    /**
    40→     * Calcule le RMS (Root Mean Square) d'un signal PCM 16-bit little-endian.
    41→     *
    42→     * PCM 16-bit : chaque échantillon = 2 bytes, valeurs de -32768 à +32767
    43→     * RMS = √(Σ(sample²) / n)
    44→     */
    45→    private double computeRms(byte[] rawData) {
    46→        if (rawData == null || rawData.length < 2) return 0.0;
    47→
    48→        long sumSquares = 0;
    49→        int sampleCount = rawData.length / 2;
    50→
    51→        for (int i = 0; i < rawData.length - 1; i += 2) {
    52→            // Little-endian : byte[i] = low byte, byte[i+1] = high byte
    53→            short sample = (short) ((rawData[i + 1] << 8) | (rawData[i] & 0xFF));
    54→            sumSquares += (long) sample * sample;
    55→        }
    56→
    57→        return Math.sqrt((double) sumSquares / sampleCount);
