    16→  padding: 0;
    17→}
    18→
    19→/* Prevent font size inflation */
    20→html {
    21→  -moz-text-size-adjust: none;
    22→  -webkit-text-size-adjust: none;
    23→  text-size-adjust: none;
    24→  scroll-behavior: smooth;
    25→}
    26→
    27→/* Set core body defaults */
    28→body {
    29→  min-height: 100vh;
    30→  line-height: var(--leading-normal, 1.5);
    31→  font-family: var(--font-body);
    32→  color: var(--text-primary);
    33→  background-color: var(--bg-primary);
    34→  -webkit-font-smoothing: antialiased;
    35→  -moz-osx-font-smoothing: grayscale;
    36→  text-rendering: optimizeLegibility;
    37→}
    38→
    39→/* Remove list styles on ul, ol elements with a list role */
    40→ul[role='list'],
    41→ol[role='list'],
    42→ul,
    43→ol {
    44→  list-style: none;
    45→}
    46→
    47→/* Set shorter line heights on headings and interactive elements */
    48→h1, h2, h3, h4, h5, h6,
    49→button,
    50→input,
    51→label {
    52→  line-height: var(--leading-tight, 1.25);
    53→}
    54→
    55→/* Balance text wrapping on headings */
    56→h1, h2, h3, h4, h5, h6 {
    57→  text-wrap: balance;
    58→  font-family: var(--font-display);
    59→  font-weight: var(--font-bold);
    60→  color: var(--text-primary);
    61→}
    62→
    63→/* Default heading sizes */
    64→h1 { font-size: var(--text-4xl); }
