    66→h3 { font-size: var(--text-2xl); }
    67→h4 { font-size: var(--text-xl); }
    68→h5 { font-size: var(--text-lg); }
    69→h6 { font-size: var(--text-base); }
    70→
    71→/* A elements that don't have a class get default styles */
    72→a:not([class]) {
    73→  text-decoration-skip-ink: auto;
    74→  color: currentColor;
    75→}
    76→
    77→/* Default anchor styles */
    78→a {
    79→  color: var(--primary-blue);
    80→  text-decoration: none;
    81→  transition: color var(--transition-fast);
    82→}
    83→
