   119→const POLL_INTERVAL = 30000; // 30 secondes
   120→
   121→let attempts = 0;
   122→let countdownValue = 30;
   123→let pollInterval;
   124→let countdownInterval;
   125→
   126→// Fonction de vérification du statut
   127→async function checkPaymentStatus() {
   128→    attempts++;
   129→
   130→    try {
   131→        const response = await fetch(`actions/check_payment_status.php?transaction_id=${encodeURIComponent(TRANSACTION_ID)}`);
   132→        const data = await response.json();
   133→
   134→        if (data.success) {
   135→            if (data.status === 'complete' || data.mapped_status === 'complete') {
   136→                showSuccess();
   137→                stopPolling();
   138→            } else if (data.status === 'echoue' || data.mapped_status === 'echoue' ||
   139→                       data.status === 'FAILED' || data.status === 'REJECTED') {
   140→                showFailed(data.reason || 'Le paiement a été refusé ou a échoué.');
   141→                stopPolling();
   142→            }
   143→            // Si toujours en attente, continuer le polling
   144→        }
   145→    } catch (error) {
   146→        console.error('Erreur lors de la vérification:', error);
   147→    }
   148→
   149→    // Arrêter après MAX_ATTEMPTS
   150→    if (attempts >= MAX_ATTEMPTS) {
   151→        showFailed('Délai d\'attente dépassé. Veuillez vérifier votre compte MTN MoMo ou réessayer.');
   152→        stopPolling();
   153→    }
   154→}
