   162→
   163→// Afficher la section échec
   164→function showFailed(message) {
   165→    document.getElementById('loading-section').classList.add('hidden');
   166→    document.getElementById('failed-section').classList.remove('hidden');
   167→    document.getElementById('error-message').textContent = message;
   168→    document.getElementById('check-manually').classList.add('hidden');
   169→}
   170→
   171→// Arrêter le polling
   172→function stopPolling() {
   173→    if (pollInterval) clearInterval(pollInterval);
   174→    if (countdownInterval) clearInterval(countdownInterval);
   175→}
   176→
   177→// Mettre à jour le compteur
   178→function updateCountdown() {
   179→    countdownValue--;
   180→    document.getElementById('countdown').textContent = countdownValue;
