   276→function updateSubscriptionPaymentStatus(PDO $pdo, string $transactionId, string $status, array $additionalData = []): bool
   277→{
   278→    try {
   279→        $sql = "UPDATE paiements_abonnement SET statut = ?";
   280→        $params = [$status];
   281→
   282→        if (!empty($additionalData['raw_response'])) {
