   285→                ? json_encode($additionalData['raw_response'])
   286→                : $additionalData['raw_response'];
   287→        }
   288→
   289→        if ($status === 'complete' && empty($additionalData['date_debut'])) {
   290→            $sql .= ", date_debut = CURDATE()";
   291→        }
   292→
   293→        $sql .= " WHERE transaction_id = ?";
   294→        $params[] = $transactionId;
   295→
   296→        $stmt = $pdo->prepare($sql);
   297→        $stmt->execute($params);
