   106→    // Préfixes MTN Cameroun
   107→    $mtnPrefixes = ['67', '68', '65', '66', '50', '51', '52', '53', '54'];
   108→    // Préfixes Orange Cameroun
   109→    $orangePrefixes = ['69', '65', '55', '56', '57', '58', '59'];
