   111→    if (in_array($prefix, $mtnPrefixes)) {
   112→        $detectedOperator = 'mtn';
   113→    } elseif (in_array($prefix, $orangePrefixes)) {
   114→        $detectedOperator = 'orange';
   115→    }
   116→
   117→    // Vérifier si l'opérateur correspond
