   270→/**
   271→ * Met à jour le statut d'un paiement d'abonnement
   272→ * @param PDO $pdo
   273→ * @param string $transactionId
   274→ * @param string $status
   275→ * @param array $additionalData
   276→ * @return bool
   277→ */
   278→function updateSubscriptionPaymentStatus(PDO $pdo, string $transactionId, string $status, array $additionalData = []): bool
   279→{
   280→    try {
   281→        $sql = "UPDATE paiements_abonnement SET statut = ?";
   282→        $params = [$status];
   283→
   284→        if (!empty($additionalData['raw_response'])) {
   285→            $sql .= ", raw_response = ?";
   286→            $params[] = is_array($additionalData['raw_response'])
   287→                ? json_encode($additionalData['raw_response'])
   288→                : $additionalData['raw_response'];
   289→        }
   290→
   291→        if ($status === 'complete' && empty($additionalData['date_debut'])) {
   292→            $sql .= ", date_debut = CURDATE()";
   293→        }
   294→
   295→        $sql .= " WHERE transaction_id = ?";
   296→        $params[] = $transactionId;
   297→
   298→        $stmt = $pdo->prepare($sql);
   299→        $stmt->execute($params);
   300→
   301→        // Si paiement réussi, activer le vendeur
   302→        if ($status === 'complete') {
   303→            activateVendorSubscription($pdo, $transactionId);
   304→        }
   305→
   306→        return $stmt->rowCount() > 0;
   307→    } catch (PDOException $e) {
   308→        error_log("Erreur updateSubscriptionPaymentStatus: " . $e->getMessage());
   309→        return false;
   310→    }
   311→}
   312→
   313→/**
   314→ * Active l'abonnement d'un vendeur après paiement réussi
   315→ * @param PDO $pdo
   316→ * @param string $transactionId
   317→ * @return bool
   318→ */
   319→function activateVendorSubscription(PDO $pdo, string $transactionId): bool
   320→{
   321→    try {
   322→        // Récupérer les infos de l'abonnement
   323→        $stmt = $pdo->prepare("SELECT * FROM paiements_abonnement WHERE transaction_id = ?");
   324→        $stmt->execute([$transactionId]);
   325→        $subscription = $stmt->fetch(PDO::FETCH_ASSOC);
   326→
   327→        if (!$subscription) {
   328→            return false;
   329→        }
   330→
   331→        // Calculer la date de fin selon la durée
   332→        $durations = [
   333→            'Mensuel' => '+1 month',
   334→            'Trimestriel' => '+3 months',
   335→            'Semestriel' => '+6 months',
   336→            'Annuel' => '+1 year'
   337→        ];
   338→
   339→        $duration = $durations[$subscription['duree']] ?? '+1 month';
   340→        $dateDebut = date('Y-m-d');
   341→        $dateFin = date('Y-m-d', strtotime($duration));
   342→
   343→        // Mettre à jour les dates
   344→        $stmt = $pdo->prepare("
   345→            UPDATE paiements_abonnement
   346→            SET date_debut = ?, date_fin = ?
   347→            WHERE transaction_id = ?
   348→        ");
   349→        $stmt->execute([$dateDebut, $dateFin, $transactionId]);
   350→
   351→        // Activer le compte vendeur
   352→        $stmt = $pdo->prepare("UPDATE users SET status = 'actif' WHERE id = ?");
   353→        $stmt->execute([$subscription['vendeur_id']]);
   354→
   355→        return true;
   356→    } catch (PDOException $e) {
   357→        error_log("Erreur activateVendorSubscription: " . $e->getMessage());
   358→        return false;
   359→    }
   360→}
