   137→                stopPolling();
   138→            } else if (data.status === 'echoue' || data.mapped_status === 'echoue' ||
   139→                       data.status === 'FAILED' || data.status === 'REJECTED') {
   140→                showFailed(data.reason || 'Le paiement a été refusé ou a échoué.');
   141→                stopPolling();
