   112→function notifyPaymentSuccess(PDO $pdo, string $transactionId)
   113→{
   114→    try {
   115→        $stmt = $pdo->prepare("
   116→            SELECT c.*, u.id as user_id, p.montant
   117→            FROM commandes c
   118→            JOIN paiements p ON c.id = p.commande_id
   119→            JOIN users u ON c.user_id = u.id
   120→            WHERE p.transaction_id = ?
   121→        ");
   122→        $stmt->execute([$transactionId]);
   123→        $commande = $stmt->fetch();
