   131→            );
   132→
   133→            // Vider le panier maintenant que le paiement est confirmé
   134→            $stmt = $pdo->prepare("DELETE FROM panier WHERE user_id = ?");
   135→            $stmt->execute([$commande['user_id']]);
   136→
   137→            // Créditer les wallets des vendeurs
   138→            creditVendeursFromCommande($pdo, $commande['id']);
   139→        }
