   145→/**
   146→ * Crédite les wallets des vendeurs pour une commande
   147→ */
   148→function creditVendeursFromCommande(PDO $pdo, int $commandeId)
   149→{
   150→    try {
   151→        require_once __DIR__ . '/../includes/WalletService.php';
   152→        $walletService = new WalletService($pdo);
   153→
   154→        // Récupérer les items de la commande groupés par vendeur
   155→        $stmt = $pdo->prepare("
   156→            SELECT vendeur_id, SUM(sous_total) as total_vendeur
   157→            FROM commande_items
   158→            WHERE commande_id = ?
   159→            GROUP BY vendeur_id
   160→        ");
   161→        $stmt->execute([$commandeId]);
   162→        $ventesParVendeur = $stmt->fetchAll(PDO::FETCH_ASSOC);
   163→
   164→        foreach ($ventesParVendeur as $vente) {
   165→            $vendeurId = $vente['vendeur_id'];
   166→            $montant = (float) $vente['total_vendeur'];
   167→
   168→            // Créditer le wallet du vendeur
   169→            $result = $walletService->crediterVenteVendeur($vendeurId, $montant, $commandeId);
   170→
   171→            if ($result['success']) {
   172→                // Notifier le vendeur
   173→                require_once __DIR__ . '/../functions.php';
   174→                pushToUsers(
   175→                    [$vendeurId],
   176→                    "Nouvelle vente!",
   177→                    "Vous avez reçu " . number_format($montant, 0) . " FCFA pour la commande #$commandeId"
   178→                );
   179→            }
   180→
   181→            logPaymentActivity('vendor_credited', [
   182→                'vendeur_id' => $vendeurId,
   183→                'commande_id' => $commandeId,
   184→                'montant' => $montant,
   185→                'result' => $result
   186→            ]);
   187→        }
   188→    } catch (Exception $e) {
   189→        error_log("creditVendeursFromCommande error: " . $e->getMessage());
