#### Phone Number Validation:
**From `/includes/payments/PaymentHelper.php`:**

```php
function validateCameroonPhone(string $phone, ?string $operator = null): array
{
    // Clean the number
    $phone = preg_replace('/[^0-9]/', '', $phone);

    // Remove country prefix if present
    if (strpos($phone, '237') === 0) {
        $phone = substr($phone, 3);
    }

    // Remove leading 0
    if (strpos($phone, '0') === 0) {
        $phone = substr($phone, 1);
    }

    // Check length (9 digits for Cameroon)
    if (strlen($phone) !== 9) {
        return ['valid' => false, 'error' => 'Le numéro doit contenir 9 chiffres'];
    }

    // Determine operator
    $prefix = substr($phone, 0, 2);
    $detectedOperator = null;

    $mtnPrefixes = ['67', '68', '65', '66', '50', '51', '52', '53', '54'];
    $orangePrefixes = ['69', '65', '55', '56', '57', '58', '59'];

    if (in_array($prefix, $mtnPrefixes)) {
        $detectedOperator = 'mtn';
    } elseif (in_array($prefix, $orangePrefixes)) {
        $detectedOperator = 'orange';
    }

    // Verify operator matches
    if ($operator && $detectedOperator !== $operator) {
        return [
            'valid' => false,
            'error' => 'Ce numéro ne semble pas être un numéro ' . strtoupper($operator)
        ];
    }

    return [
        'valid' => true,
        'formatted' => '237' . $phone,
        'local' => $phone,
        'operator' => $detectedOperator
    ];
}
```

