function logSubscriptionPayment(PDO $pdo, array $data)
{
    try {
        $stmt = $pdo->prepare("
            INSERT INTO paiements_abonnement (
                vendeur_id, plan_nom, duree, montant, mode_paiement,
                statut, transaction_id, phone_number, date_debut, date_fin
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ");

        $stmt->execute([
            $data['vendeur_id'],
            $data['plan_nom'],
            $data['duree'],
            $data['montant'],
            $data['mode_paiement'],
            $data['statut'] ?? 'en_attente',
            $data['transaction_id'],
            $data['phone_number'] ?? null,
            $data['date_debut'] ?? date('Y-m-d'),
            $data['date_fin'] ?? null
        ]);

        return $pdo->lastInsertId();
    } catch (PDOException $e) {
        error_log("Erreur logSubscriptionPayment: " . $e->getMessage());
        return false;
    }
}
```

