   261→     * @return string Numéro formaté
   262→     */
   263→    protected function formatPhoneNumber(string $phone, string $countryCode = '237'): string
   264→    {
   265→        // Supprimer tous les caractères non numériques
   266→        $phone = preg_replace('/[^0-9]/', '', $phone);
   267→
   268→        // Si le numéro commence déjà par le code pays, le retourner
   269→        if (strpos($phone, $countryCode) === 0) {
   270→            return $phone;
   271→        }
   272→
   273→        // Supprimer le 0 initial si présent
   274→        if (strpos($phone, '0') === 0) {
   275→            $phone = substr($phone, 1);
   276→        }
   277→
   278→        return $countryCode . $phone;
   279→    }
