   282→     * Valide un numéro de téléphone
   283→     * @param string $phone Numéro à valider
   284→     * @return bool
   285→     */
   286→    protected function isValidPhoneNumber(string $phone): bool
   287→    {
   288→        $phone = preg_replace('/[^0-9]/', '', $phone);
   289→        return strlen($phone) >= 9 && strlen($phone) <= 15;
