   278→ */
   279→function requireActiveSubscription($allowExpired = false)
   280→{
   281→    global $pdo;
   282→    $userId = getUserId();
   283→
   284→    if (!$userId) {
   285→        flashMessage('error', 'Vous devez être connecté.');
   286→        redirect('../index.php?page=connexion');
   287→    }
   288→
   289→    // Vérifier le statut du vendeur dans users
   290→    $stmt = $pdo->prepare("SELECT status FROM users WHERE id = ?");
   291→    $stmt->execute([$userId]);
   292→    $user = $stmt->fetch(PDO::FETCH_ASSOC);
   293→
   294→    if (!$user) {
   295→        flashMessage('error', 'Utilisateur introuvable.');
   296→        redirect('../index.php');
   297→    }
   298→
   299→    // Cas 1: Vendeur en attente (jamais activé)
   300→    if ($user['status'] === 'en_attente') {
   301→        flashMessage('info', 'Veuillez choisir un pack pour activer votre compte vendeur.');
   302→        redirect('activation.php');
   303→    }
   304→
   305→    // Cas 2: Vendeur inactif (désactivé par admin)
   306→    if ($user['status'] === 'inactif') {
   307→        flashMessage('error', 'Votre compte a été désactivé. Contactez l\'administrateur.');
   308→        redirect('../index.php');
   309→    }
   310→
   311→    // Cas 3: Vendeur actif - vérifier l'abonnement
   312→    $subscriptionStatus = checkVendorSubscription($userId);
   313→
   314→    // Si abonnement expiré et qu'on n'autorise pas l'accès
   315→    if (!$subscriptionStatus['active'] && !$allowExpired) {
   316→        flashMessage('warning', 'Votre abonnement a expiré. Veuillez le renouveler pour continuer à vendre.');
   317→        redirect('tarifs.php');
   318→    }
   319→
   320→    return [
   321→        'active' => $subscriptionStatus['active'],
   322→        'subscription' => $subscriptionStatus['subscription'],
   323→        'expires_in' => $subscriptionStatus['expires_in']
   324→    ];
   325→}
