import json
from redactor import redact_session
from collections import Counter

findings_by_type = Counter()
sessions_with_redactions = 0
total = 0

with open('/tmp/conversations.jsonl') as f:
    for line in f:
        s = json.loads(line)
        total += 1
        _, n = redact_session(s)
        if n > 0:
            sessions_with_redactions += 1
            # Re-scan pour compter par type
            from redactor import scan_text
            for turn in s.get('turns', []):
                for field in ('user', 'summary'):
                    if turn.get(field):
                        for finding in scan_text(turn[field]):
                            findings_by_type[finding['type']] += 1
                asst = turn.get('assistant', {})
                for field in ('thinking', 'text'):
                    if asst.get(field):
                        for finding in scan_text(asst[field]):
                            findings_by_type[finding['type']] += 1
                for tc in asst.get('tool_calls', []):
                    for field in ('stdout', 'stderr', 'output'):
                        v = tc.get(field, '')
                        if isinstance(v, str):
                            for finding in scan_text(v):
                                findings_by_type[finding['type']] += 1

print(f'Sessions analysées  : {total}')
print(f'Avec redactions     : {sessions_with_redactions}')
print()
print('Types détectés :')
for t, n in findings_by_type.most_common():
    print(f'  {t:<25} : {n}')
"

